import type { RealtimePrediction } from "tfl-ts"
import {
  ArrivalsBoardSkeleton,
  ArrivalsBoardView,
  resolveArrivalsHeading,
  type ArrivalsBoardChromeProps,
  type ArrivalsBoardClassNames,
} from "@/components/tfl/arrivals/arrivals-board-view"
import type { BusStopDisruption } from "@/lib/tfl/prepare-bus-stop-disruptions"
import {
  prepareBusArrivals,
  type BusArrivalsGroupBy,
  type BusArrivalsGroupSortBy,
  type BusArrivalsSortBy,
} from "@/lib/tfl/arrivals-prepare"
import { RIVER_ARRIVALS_EMPTY_COPY } from "@/lib/tfl/arrivals-empty"
import { filterRiverBusArrivals, isRiverBusLineId } from "@/lib/tfl/river-bus"
import type { DisplayBehaviour } from "@/lib/tfl/unattended-sequence"

export type RiverBusArrivalsBoardProps = ArrivalsBoardChromeProps & {
  /**
   * Normalised arrivals from `tfl.stopPoint.getArrivals` (`RealtimePrediction[]`).
   * Missing/`undefined` treated as an empty list. The board sorts this itself.
   * Poll the pier (`NaptanFerryPort`, `930G…`), not a berth.
   */
  data?: readonly RealtimePrediction[]
  /**
   * Per-route disruption warnings for this pier. Build with
   * `prepareBusStopDisruptions` from `stopPoint.getDisruption` output —
   * fetching stays in your app/demo, same as `data`.
   */
  disruptions?: readonly BusStopDisruption[]
  /**
   * `none` (default) is one flat list in arrival-time order, route chip on
   * every row. `route` groups by river-bus line.
   */
  groupBy?: BusArrivalsGroupBy
  /** Arrival order. Default `timeToStation` (global when flat, per route when grouped). */
  sortBy?: BusArrivalsSortBy
  /** Route-group order when `groupBy="route"`. Default `route` (RB1 before RB6). */
  groupSortBy?: BusArrivalsGroupSortBy
  /** Cap on prediction rows after ordering. Headers do not count. */
  maxRows?: number
  /**
   * Fetch timestamp (ms) captured with `data`. Drops predictions whose
   * `timeToLive` has already expired. Must not be a ticking clock —
   * river `timeToLive` is a ~1–2 min feed TTL, not arrival expiry.
   * Omit to skip this filter.
   */
  now?: number
  /**
   * Visible arrivals per page. Grouped: per route, arrows on the route header.
   * Flat: the whole list, arrows always visible in a trailing tile. Once
   * there is more than one page, the list locks to this height. Default 3.
   */
  pageSize?: number
  behaviour?: DisplayBehaviour
  pinFirst?: boolean
  dwellMs?: number
  startDelayMs?: number
  idleReturnMs?: number
  className?: string
  classNames?: ArrivalsBoardClassNames
}

export const RiverBusArrivalsBoardSkeleton = ({
  className,
  stopName,
}: {
  className?: string
  stopName?: string
} = {}) => (
  <ArrivalsBoardSkeleton
    mode="river"
    className={className}
    stopName={stopName}
  />
)

/**
 * River bus arrivals board. Default is a flat time-ordered list with a
 * river-blue route chip on every row. Fetching stays in the app.
 *
 * Grouping reuses `prepareBusArrivals` — river has no compass-bound level,
 * same shape as bus routes.
 */
export const RiverBusArrivalsBoard = ({
  data,
  disruptions,
  groupBy = "none",
  sortBy = "timeToStation",
  groupSortBy = "route",
  maxRows = 16,
  now,
  pageSize = 3,
  behaviour,
  pinFirst,
  dwellMs,
  startDelayMs,
  idleReturnMs,
  loading = false,
  error = null,
  emptyMessage = RIVER_ARRIVALS_EMPTY_COPY,
  className,
  classNames,
  ...chrome
}: RiverBusArrivalsBoardProps) => {
  const rows = filterRiverBusArrivals(data)
  const heading = resolveArrivalsHeading(chrome.stopName, rows)
  if (loading && rows.length === 0 && !error) {
    return (
      <RiverBusArrivalsBoardSkeleton className={className} stopName={heading} />
    )
  }

  const prepared = prepareBusArrivals({
    data: rows,
    groupBy,
    sortBy,
    groupSortBy,
    now,
    maxRows,
  })
  const riverDisruptions = (disruptions ?? []).filter((item) =>
    isRiverBusLineId(item.lineId)
  )

  return (
    <ArrivalsBoardView
      mode="river"
      prepared={prepared}
      disruptions={riverDisruptions}
      loading={loading}
      error={error}
      emptyMessage={emptyMessage}
      pageSize={pageSize}
      behaviour={behaviour}
      pinFirst={pinFirst}
      dwellMs={dwellMs}
      startDelayMs={startDelayMs}
      idleReturnMs={idleReturnMs}
      className={className}
      classNames={classNames}
      {...chrome}
      stopName={heading}
    />
  )
}

export type { ArrivalsBoardClassNames }
export type { BusStopDisruption } from "@/lib/tfl/prepare-bus-stop-disruptions"
export { prepareBusStopDisruptions } from "@/lib/tfl/prepare-bus-stop-disruptions"
export type {
  BusArrivalsGroupBy,
  BusArrivalsGroupSortBy,
  BusArrivalsSortBy,
} from "@/lib/tfl/arrivals-prepare"
export type { RealtimePrediction } from "tfl-ts"

import type { CSSProperties } from "react"
import {
  ARRIVALS_IDENTITY_CHIP_WIDTH_CLASS,
  CHIP_CAP_TEXT_BOX_CLASS,
} from "@/components/tfl/arrivals/chip-text"
import { TFL_MODAL_COLOURS } from "@/lib/tfl/brand-colours"
import { riverRouteChipCopy } from "@/lib/tfl/river-bus"
import { cn } from "@/lib/utils"

export type RiverRouteChipProps = {
  /** Line id (`rb1`, `woolwich-ferry`). */
  lineId?: string
  /** Display name from TfL (`RB1`, `Woolwich Ferry`). */
  lineName?: string
  className?: string
  style?: CSSProperties
}

/**
 * River-bus route chip — River Services blue, fixed `5ch`, square corners.
 * Woolwich Ferry paints `WF`; the accessible name stays the full line name.
 */
export const RiverRouteChip = ({
  lineId,
  lineName,
  className,
  style,
}: RiverRouteChipProps) => {
  const { label, ariaLabel } = riverRouteChipCopy(lineId, lineName)
  if (!label) return null
  return (
    <span
      className={cn(
        "inline-flex h-5 shrink-0 items-center justify-center text-center text-xs font-bold text-white tabular-nums",
        ARRIVALS_IDENTITY_CHIP_WIDTH_CLASS,
        className
      )}
      style={{ backgroundColor: TFL_MODAL_COLOURS.river.hex, ...style }}
      aria-label={ariaLabel}
    >
      <span className={CHIP_CAP_TEXT_BOX_CLASS}>{label}</span>
    </span>
  )
}

import { LINE_STATION_SEQUENCES } from "tfl-ts"

/** Live river-bus line ids from tfl-ts `LINE_STATION_SEQUENCES`. */
export const RIVER_BUS_LINE_IDS = Object.values(LINE_STATION_SEQUENCES)
  .filter((sequence) => sequence.modeName === "river-bus")
  .map((sequence) => sequence.lineId)
  .sort((a, b) => a.localeCompare(b, "en"))

export type RiverBusLineId = (typeof RIVER_BUS_LINE_IDS)[number]

export const RIVER_BUS_LINE_ID_SET: ReadonlySet<string> = new Set(
  RIVER_BUS_LINE_IDS
)

export const FERRY_PORT_STOP_TYPE = "NaptanFerryPort"

/** Parent pier ids (`930G…`). Berths (`9300…`) return no arrivals. */
export const isFerryPortId = (id: string): boolean => /^930G/i.test(id.trim())

/** Trim, lower-case, spaces → hyphens. `"Woolwich Ferry"` → `woolwich-ferry`. */
export const canonicalRiverLineId = (lineId: string): string =>
  lineId.trim().toLowerCase().replace(/\s+/g, "-")

export const isRiverBusLineId = (lineId: string): boolean =>
  RIVER_BUS_LINE_ID_SET.has(canonicalRiverLineId(lineId))

export const filterRiverBusLineIds = (
  lineIds: readonly string[] | undefined
): string[] =>
  [...new Set((lineIds ?? []).map(canonicalRiverLineId))].filter((id) =>
    RIVER_BUS_LINE_ID_SET.has(id)
  )

/** Keep only live river-bus predictions. Putney StopPoints also list bus routes. */
export const filterRiverBusArrivals = <T extends { lineId?: string }>(
  rows: readonly T[] | undefined
): T[] => (rows ?? []).filter((row) => isRiverBusLineId(row.lineId ?? ""))

export const pointHasRiverBusLine = (
  lineIds: readonly string[] | undefined
): boolean => (lineIds ?? []).some((id) => isRiverBusLineId(id))

/**
 * Chip paint vs accessible name. Woolwich Ferry does not fit 5ch.
 * `aria-label` is the full line name, not the abbreviated chip.
 */
export const riverRouteChipCopy = (
  lineId?: string,
  lineName?: string
): { label: string; ariaLabel: string } => {
  const id = (lineId ?? "").trim().toLowerCase()
  const name = lineName?.trim()
  if (id === "woolwich-ferry") {
    return { label: "WF", ariaLabel: name || "Woolwich Ferry" }
  }
  const label = id ? id.toUpperCase() : (name ?? "")
  return { label, ariaLabel: name || label }
}

import type { CSSProperties } from "react"
import { normalizeLineId, type RealtimePrediction } from "tfl-ts"
import { TfLRoundel } from "@/components/tfl/brand/tfl-roundel"
import type { RoundelPreset } from "@/lib/tfl/roundel-presets"
import { StationNameTitle } from "@/components/tfl/station-name"
import {
  BusStopDisruptionBoundary,
  BusStopDisruptionChips,
  BusStopDisruptionCover,
} from "@/components/tfl/arrivals/bus-stop-disruptions"
import type { BusStopDisruption } from "@/lib/tfl/prepare-bus-stop-disruptions"
import {
  ARRIVALS_EMPTY_COPY,
  ARRIVALS_LINE_EMPTY_COPY,
  type ArrivalsEmptyKind,
} from "@/lib/tfl/arrivals-empty"
import type {
  ArrivalsPreparedBoard,
  ArrivalsPreparedGroup,
} from "@/lib/tfl/arrivals-prepare"
import { StopLetterBadge } from "@/components/tfl/arrivals/stop-letter-badge"
import { cn } from "@/lib/utils"
import { Skeleton } from "@/components/ui/skeleton"
import {
  ArrivalsBoundGroup,
  ArrivalsGroupHeader,
  ArrivalsPagedGroup,
  ArrivalsPagedList,
  type ArrivalsBoardClassNames,
} from "@/components/tfl/arrivals/arrivals-bound-group"
import type { DisplayBehaviour } from "@/lib/tfl/unattended-sequence"

export type { DisplayBehaviour }

export type ArrivalsBoardMode = "rail" | "bus" | "river"

const arrivalsRoundelVariant = (mode: ArrivalsBoardMode): RoundelPreset => {
  if (mode === "bus") return "buses"
  if (mode === "river") return "river"
  return "underground"
}

const isRouteArrivalsMode = (mode: ArrivalsBoardMode): boolean =>
  mode === "bus" || mode === "river"

export type { ArrivalsBoardClassNames }
export {
  formatArrivalsCountdown,
  getArrivalsPlatformNumber,
} from "@/components/tfl/arrivals/arrivals-bound-group"

export type ArrivalsBoardChromeProps = {
  /**
   * Board heading. Omit to use `data[].stationName` from the predictions.
   * Fits via abbr/scale, same policy as destinations.
   */
  stopName?: string
  /**
   * @deprecated Dev/meta NaPTAN id — not shown in the board UI. Kept for call-site compat.
   */
  stopPointId?: string
  /**
   * Bus stop letter (e.g. "G"). Prefer this over sniffing `platformName` on rows —
   * it is a stop property, not a per-arrival field.
   */
  stopLetter?: string
  /**
   * @deprecated Board heading is always `stopName`. Kept for call-site compat; ignored.
   */
  title?: string
  /** Semantic heading level for the stop name. Prefer `2` when embedded under a page `h1`. */
  headingLevel?: 1 | 2
  loading?: boolean
  /**
   * Fetch/render failure. Takes precedence over an empty list.
   * Prefer a short human line — raw API strings read as broken UI.
   */
  error?: string | null
  /** Optional short caption in the title row. Prefer app-chrome freshness over poll counts. */
  statusLabel?: string
  /**
   * Why the board has no rows when `error` is unset.
   * Resolve in the app (`resolveArrivalsEmptyKind`) from clock / offline / domain.
   */
  emptyKind?: ArrivalsEmptyKind
  /** Override copy for `emptyKind`. Prefer setting `emptyKind` instead. */
  emptyMessage?: string
}

/**
 * Baseline grid. Every block is a whole number of `--arrivals-unit` (0.5rem):
 * arrival row, board title, and line header are all 6 units, direction labels 6
 * (same as line names). Two boards side by side land on the same horizontal lines.
 * Override the vars on a wrapper to retune density.
 */
export const ARRIVALS_RHYTHM_VARS = {
  "--arrivals-unit": "0.5rem",
  "--arrivals-row": "calc(var(--arrivals-unit) * 6)",
} as CSSProperties

/**
 * Fixed tile box. Height is always exactly one rhythm row — content may clip,
 * but borders/bars must never grow the tile (`box-border` + `overflow-clip`).
 * Clip, not `hidden`: tiles must not become scroll containers above the page track.
 */
export const ARRIVALS_TILE_CLASS =
  "box-border h-[var(--arrivals-row)] min-h-[var(--arrivals-row)] max-h-[var(--arrivals-row)] min-w-0 shrink-0 overflow-clip"

const TITLE_CLASS =
  "tfl-title [font-synthesis:none] [font-weight:var(--tfl-title-weight,400)] [letter-spacing:var(--tfl-title-tracking,0)]"

const LIST_RESET_CLASS = "m-0 ml-0 list-none space-y-0 p-0 [&>li]:mt-0"

export {
  getBusStopLetterFromPlatform,
  resolveBusStopLetter,
} from "@/lib/tfl/bus-stop-letter"

/** Explicit `stopName` wins; otherwise the first non-empty `stationName` on `data`. */
export const resolveArrivalsHeading = (
  stopName: string | undefined,
  data?: readonly Pick<RealtimePrediction, "stationName">[]
): string | undefined => {
  const override = stopName?.trim()
  if (override) return override
  for (const row of data ?? []) {
    const name = row.stationName?.trim()
    if (name) return name
  }
  return undefined
}

export { StopLetterBadge } from "@/components/tfl/arrivals/stop-letter-badge"

export const ArrivalsBoardSkeleton = ({
  mode = "rail",
  className,
  stopName,
  stopLetter,
}: {
  mode?: ArrivalsBoardMode
  className?: string
  /** Known stop identity — paint immediately; do not wait on predictions. */
  stopName?: string
  stopLetter?: string
}) => (
  <div
    data-slot="arrivals-board"
    className={cn("@container/arrivals min-w-0 w-full", className)}
    style={ARRIVALS_RHYTHM_VARS}
    aria-busy
    aria-label="Loading arrivals"
  >
    <div
      className={cn(
        "flex min-w-0 items-center gap-x-3 text-3xl",
        ARRIVALS_TILE_CLASS
      )}
    >
      {stopName ? (
        <>
          <TfLRoundel
            variant={arrivalsRoundelVariant(mode)}
            className="size-[var(--arrivals-row)] shrink-0"
            aria-hidden
          />
          <p
            className={cn(
              "flex h-full min-w-0 flex-1 items-center text-3xl",
              TITLE_CLASS
            )}
          >
            <StationNameTitle name={stopName} />
          </p>
          {stopLetter ? <StopLetterBadge letter={stopLetter} /> : null}
        </>
      ) : (
        <Skeleton className="h-8 w-56 max-w-full" />
      )}
    </div>
    {isRouteArrivalsMode(mode) ? (
      <div>
        {Array.from({ length: 6 }).map((_, rowIndex) => (
          <div
            key={rowIndex}
            className={cn("flex items-center", ARRIVALS_TILE_CLASS)}
          >
            <Skeleton className="h-5 w-full" />
          </div>
        ))}
      </div>
    ) : (
      Array.from({ length: 2 }).map((_, sectionIndex) => (
        <div key={sectionIndex}>
          <div
            className={cn(
              "flex items-center border-b-4 border-border",
              ARRIVALS_TILE_CLASS
            )}
          >
            <Skeleton className="h-6 w-28" />
          </div>
          {Array.from({ length: 4 }).map((_, rowIndex) => (
            <div
              key={rowIndex}
              className={cn("flex items-center", ARRIVALS_TILE_CLASS)}
            >
              <Skeleton className="h-5 w-full" />
            </div>
          ))}
        </div>
      ))
    )}
  </div>
)

const GroupBody = ({
  group,
  mode,
  pageSize,
  classNames,
  behaviour,
  pinFirst,
  dwellMs,
  startDelayMs,
  idleReturnMs,
}: {
  group: ArrivalsPreparedGroup
  mode: ArrivalsBoardMode
  pageSize?: number
  classNames?: ArrivalsBoardClassNames
  behaviour?: DisplayBehaviour
  pinFirst?: boolean
  dwellMs?: number
  startDelayMs?: number
  idleReturnMs?: number
}) => {
  const labeledBounds = group.bounds.filter((bound) => bound.label)
  // `grid-cols-1` (not block) so consumer `grid-cols-*` variants merge cleanly.
  const subgroupsClassName = cn(
    LIST_RESET_CLASS,
    "min-w-0 grid grid-cols-1",
    classNames?.subgroups
  )

  if (!group.hasInformation && labeledBounds.length === 0) {
    const lockHeight = (pageSize ?? 0) > 0
    const dashCount = lockHeight ? Math.max(0, (pageSize ?? 1) - 1) : 0
    return (
      <ul
        data-slot="arrivals-subgroups"
        className={subgroupsClassName}
        role="list"
      >
        <li
          data-slot="arrivals-row"
          className={cn(
            "flex items-center text-base text-muted-foreground",
            ARRIVALS_TILE_CLASS
          )}
          aria-label={`${group.lineName}: ${ARRIVALS_LINE_EMPTY_COPY}`}
        >
          {ARRIVALS_LINE_EMPTY_COPY}
        </li>
        {Array.from({ length: dashCount }, (_, index) => (
          <li
            key={`dash-${index}`}
            data-slot="arrivals-row"
            aria-hidden
            className={cn(
              "flex items-center text-base text-muted-foreground/50",
              ARRIVALS_TILE_CLASS
            )}
          >
            —
          </li>
        ))}
      </ul>
    )
  }

  return (
    <ul
      data-slot="arrivals-subgroups"
      className={subgroupsClassName}
      role="list"
    >
      {group.bounds.map((bound, index) => (
        <ArrivalsBoundGroup
          key={bound.key}
          bound={bound}
          mode={mode}
          lineName={group.lineName}
          isLastBound={index === group.bounds.length - 1}
          pageSize={pageSize}
          showLineChip={group.lineIds.length > 1}
          classNames={classNames}
          behaviour={behaviour}
          pinFirst={pinFirst}
          idleReturnMs={idleReturnMs}
          dwellMs={dwellMs}
          startDelayMs={startDelayMs}
        />
      ))}
    </ul>
  )
}

/** Resolve per-line page size; falls back to the board-wide scalar. */
export const resolveGroupPageSize = (
  lineId: string,
  pageSize: number | undefined,
  pageSizeByLine: Readonly<Record<string, number>> | undefined,
  lineIds?: readonly string[]
): number | undefined => {
  if (!pageSizeByLine) return pageSize
  const ids = lineIds?.length ? lineIds : [lineId]
  for (const id of ids) {
    const keyed = pageSizeByLine[normalizeLineId(id)]
    if (typeof keyed === "number") return keyed
    const raw = pageSizeByLine[id]
    if (typeof raw === "number") return raw
  }
  return pageSize
}

export type ArrivalsBoardViewProps = ArrivalsBoardChromeProps & {
  mode: ArrivalsBoardMode
  prepared: ArrivalsPreparedBoard
  resolvedStopLetter?: string | null
  /**
   * Bus and river. Per-route disruption warnings — build with
   * `prepareBusStopDisruptions` from `stopPoint.getDisruption` output.
   * Renders a warning chip per route in the header; hover/tap covers the
   * rows below with that route's description.
   */
  disruptions?: readonly BusStopDisruption[]
  /**
   * Visible arrivals per page. Rail: fixed subgroup height — every bound
   * occupies exactly this many arrival tiles (short pages fill with dashes
   * and an end-of-list message). Bus grouped / flat: same lock once there
   * is more than one page; a short unpaged list keeps its natural height.
   * Omit or `0` to show the prepared rows at natural height.
   */
  pageSize?: number
  /**
   * Rail only: ID-keyed rows-per-bound override. Falls back to `pageSize`
   * for lines not listed. Each value applies to every bound on that line.
   */
  pageSizeByLine?: Readonly<Record<string, number>>
  /** Interactive pager vs unattended auto-advance. Default interactive. */
  behaviour?: DisplayBehaviour
  /** Unattended: keep the first arrival visible while later slots rotate. */
  pinFirst?: boolean
  dwellMs?: number
  startDelayMs?: number
  /** Interactive: return to page 1 after this many idle milliseconds. */
  idleReturnMs?: number
  /**
   * Root classes, merged over the board container (`data-slot="arrivals-board"`).
   * The root *is* the `arrivals` container, so container-query variants here
   * query an outer context — put board-width arrangements on `classNames.groups`
   * instead.
   */
  className?: string
  /**
   * Layout-level class overrides for generated parts (`data-slot` per level).
   * CSS-first: arrange line sections via `groups`, bound columns via
   * `subgroups` — no JavaScript layout config.
   */
  classNames?: ArrivalsBoardClassNames
}

/**
 * Shared arrivals presentation. Domain boards prepare grouping and order;
 * this paints the already-resolved structure.
 */
export const ArrivalsBoardView = ({
  mode,
  prepared,
  stopName,
  resolvedStopLetter,
  disruptions = [],
  headingLevel = 1,
  loading = false,
  error = null,
  statusLabel,
  emptyKind = "empty",
  emptyMessage,
  pageSize,
  pageSizeByLine,
  behaviour,
  pinFirst,
  dwellMs,
  startDelayMs,
  idleReturnMs,
  className,
  classNames,
}: ArrivalsBoardViewProps) => {
  const TitleTag = headingLevel === 2 ? "h2" : "h1"
  const emptyCopy = emptyMessage ?? ARRIVALS_EMPTY_COPY[emptyKind]
  const showEmpty =
    !error &&
    !loading &&
    prepared.rows.length === 0 &&
    prepared.groups.length === 0
  const showStopDisruptions = mode === "bus" || mode === "river"
  const hasStopDisruptionChips = showStopDisruptions && disruptions.length > 0

  return (
    <div
      data-slot="arrivals-board"
      className={cn("@container/arrivals min-w-0 w-full", className)}
      style={ARRIVALS_RHYTHM_VARS}
    >
      <BusStopDisruptionBoundary
        disruptions={showStopDisruptions ? disruptions : []}
        variant={mode === "river" ? "river" : "bus"}
      >
        <div
          className={cn(
            "flex min-w-0 items-center gap-x-3 text-3xl",
            ARRIVALS_TILE_CLASS,
            hasStopDisruptionChips && "overflow-visible"
          )}
        >
          <TfLRoundel
            variant={arrivalsRoundelVariant(mode)}
            className="size-[var(--arrivals-row)] shrink-0"
            aria-hidden
          />
          {stopName ? (
            <TitleTag
              className={cn(
                "flex h-full min-w-0 flex-1 items-center",
                TITLE_CLASS
              )}
              aria-label={stopName}
            >
              <StationNameTitle
                name={stopName}
                end={
                  hasStopDisruptionChips ? (
                    <BusStopDisruptionChips />
                  ) : undefined
                }
              />
            </TitleTag>
          ) : loading ? (
            <Skeleton className="h-8 w-56 max-w-full" />
          ) : (
            <TitleTag className={cn("min-w-0 flex-1", TITLE_CLASS)}>
              <span className="sr-only">Arrivals</span>
            </TitleTag>
          )}
          {resolvedStopLetter ? (
            <StopLetterBadge letter={resolvedStopLetter} />
          ) : null}
          {statusLabel ? (
            <p className="flex shrink-0 items-center gap-2 text-xs text-muted-foreground">
              {statusLabel}
            </p>
          ) : null}
        </div>
        <BusStopDisruptionCover />

        {error ? (
          <p
            className={cn(
              "flex items-center truncate text-base text-destructive",
              ARRIVALS_TILE_CLASS
            )}
            role="alert"
          >
            {error}
          </p>
        ) : null}

        {showEmpty ? (
          <p
            className={cn(
              "flex items-center text-base text-muted-foreground",
              ARRIVALS_TILE_CLASS
            )}
            role="status"
          >
            {emptyCopy}
          </p>
        ) : null}

        {prepared.layout === "flat" ? (
          <ArrivalsPagedList
            rows={prepared.rows}
            mode={mode}
            pageSize={pageSize}
            classNames={classNames}
            behaviour={behaviour}
            pinFirst={pinFirst}
            idleReturnMs={idleReturnMs}
            dwellMs={dwellMs}
            startDelayMs={startDelayMs}
          />
        ) : isRouteArrivalsMode(mode) ? (
          <div
            data-slot="arrivals-groups"
            className={cn("grid min-w-0 grid-cols-1", classNames?.groups)}
          >
            {prepared.groups.map((group, index) => (
              <ArrivalsPagedGroup
                key={group.key}
                group={group}
                mode={mode}
                headingLevel={headingLevel}
                pageSize={pageSize}
                isLastGroup={index === prepared.groups.length - 1}
                classNames={classNames}
                behaviour={behaviour}
                pinFirst={pinFirst}
                idleReturnMs={idleReturnMs}
                dwellMs={dwellMs}
                startDelayMs={startDelayMs}
              />
            ))}
          </div>
        ) : (
          <div
            data-slot="arrivals-groups"
            className={cn("grid min-w-0 grid-cols-1", classNames?.groups)}
          >
            {prepared.groups.map((group) => (
              <section
                key={group.key}
                data-slot="arrivals-group"
                data-line={
                  group.lineIds.length > 1
                    ? undefined
                    : group.lineId || undefined
                }
                className={cn(
                  "@container/arrivals-group min-w-0",
                  classNames?.group
                )}
              >
                <ArrivalsGroupHeader
                  group={group}
                  mode={mode}
                  headingLevel={headingLevel}
                />
                <GroupBody
                  group={group}
                  mode={mode}
                  pageSize={resolveGroupPageSize(
                    group.lineId,
                    pageSize,
                    pageSizeByLine,
                    group.lineIds
                  )}
                  classNames={classNames}
                  behaviour={behaviour}
                  pinFirst={pinFirst}
                  idleReturnMs={idleReturnMs}
                  dwellMs={dwellMs}
                  startDelayMs={startDelayMs}
                />
              </section>
            ))}
          </div>
        )}
      </BusStopDisruptionBoundary>
    </div>
  )
}

