  platformLabel: string | null
  /** Inner/Outer Rail qualifier, when the platform carries one (Paddington/Bayswater/Notting Hill Gate Circle/H&C). */
  railDesignation: ArrivalsRailDesignation | null
  /**
   * True when every row in this bound shares one known platform — hoist it
   * into the heading and omit the per-row chip.
   */
  platformUniform: boolean
  /** True when this bound was empty before maxRows (metadata seed). */
  seededEmpty: boolean
  rows: ArrivalsPreparedRow[]
}

export type ArrivalsPreparedGroup = {
  key: string
  /** Primary line id (canonical-first member when merged). */
  lineId: string
  /** One id, or every member of a `lineGroups` merge. */
  lineIds: readonly string[]
  lineName: string
  modeName?: string
  kind: "rail-line" | "bus-route"
  hasInformation: boolean
  /** True when the group had no predictions before maxRows. */
  seededEmpty: boolean
  bounds: ArrivalsPreparedBound[]
}

/**
 * Merge several line ids into one board section (shared platforms).
 * Off by default — the caller opts in. Groups with fewer than two ids are ignored.
 */
export type RailArrivalsLineGroup = {
  lines: readonly string[]
  /** Override the joined header. Default: TfL list grammar via `joinLineNames`. */
  label?: string
}

export type ArrivalsPreparedBoard = {
  layout: "grouped" | "flat"
  groups: ArrivalsPreparedGroup[]
  rows: ArrivalsPreparedRow[]
}

export const indexArrivals = (
  data: readonly RealtimePrediction[] | undefined
): IndexedArrival[] =>
  (data ?? []).map((arrival, sourceIndex) => ({ arrival, sourceIndex }))

/**
 * TfL's own field: "the expiry time for the prediction". Confirmed live on
 * Weaver at Liverpool Street and Elizabeth line at Paddington — a
 * "self-destination" row (destination equals the station you're standing
 * at, no direction) reports `timeToLive` a fixed ~1 minute in the past while
 * `timeToStation` keeps counting up for up to two hours. TfL is telling the
 * client this record already expired; `timeToStation` is a stale leftover.
 * Underground rows never trip this — their `timeToLive` always tracks
 * `expectedArrival` exactly, so it's never "expired" before the train has
 * actually arrived. See docs/arrivals-shared-platforms.md.
 */
export const isExpiredArrivalPrediction = (
  arrival: RealtimePrediction,
  now: number
): boolean => {
  const timeToLive = arrival.timeToLive
  if (!timeToLive) return false
  const expiry = Date.parse(timeToLive)
  return Number.isFinite(expiry) && expiry < now
}

export const compareIndexedByTime = (
  a: IndexedArrival,
  b: IndexedArrival
): number => {
  const timeDiff =
    (a.arrival.timeToStation ?? 0) - (b.arrival.timeToStation ?? 0)
  if (timeDiff !== 0) return timeDiff
  return a.sourceIndex - b.sourceIndex
}

export const compareIndexedBySource = (
  a: IndexedArrival,
  b: IndexedArrival
): number => a.sourceIndex - b.sourceIndex

const sortIndexed = (
  items: readonly IndexedArrival[],
  sortBy: "timeToStation" | "source"
): IndexedArrival[] =>
  [...items].sort(
    sortBy === "source" ? compareIndexedBySource : compareIndexedByTime
  )

/**
 * TfL omits a real train id as blank or all zeros (`"000"`). Those are not
 * one vehicle — collapsing them deletes distinct arrivals.
 */
const isUsableVehicleId = (
  vehicleId: string | undefined
): vehicleId is string => {
  const trimmed = vehicleId?.trim()
  if (!trimmed) return false
  return !/^0+$/.test(trimmed)
}

const normalizeIdentityPart = (value?: string): string =>
  value?.trim().toLowerCase() ?? ""

/**
 * Stable prediction identity. Independent of source-array position, rank,
 * page, countdown, timestamp, current location, and shared-track presentation.
 * Raw `lineId` is used on purpose — `sharedTrackIdentity` is a derived tag.
 */
export const arrivalIdentityKey = (arrival: RealtimePrediction): string =>
  [
    normalizeIdentityPart(arrival.naptanId),
    normalizeIdentityPart(arrival.lineId),
    normalizeIdentityPart(arrival.direction),
    normalizeIdentityPart(arrival.platformName),
    normalizeIdentityPart(arrival.tripId),
    isUsableVehicleId(arrival.vehicleId)
      ? normalizeIdentityPart(arrival.vehicleId)
      : "",
    normalizeIdentityPart(arrival.destinationNaptanId),
    normalizeIdentityPart(arrival.id),
  ].join("|")

/**
 * Assign React keys for a sibling list. Distinct predictions keep a field
 * composite. When TfL repeats that composite, `expectedArrival` breaks the
 * tie. Fully identical rows stay separate with a last-resort suffix so the
 * board does not collapse two predictions into one tile.
 */
const assignPreparedRows = (
  items: readonly IndexedArrival[]
): ArrivalsPreparedRow[] => {
  const bases = items.map((item) => arrivalIdentityKey(item.arrival))
  const groups = new Map<string, number[]>()
  for (const [index, base] of bases.entries()) {
    const list = groups.get(base)
    if (list) list.push(index)
    else groups.set(base, [index])
  }

  const keys = new Array<string>(items.length)
  for (const [base, indexes] of groups) {
    if (indexes.length === 1) {
      keys[indexes[0]!] = base
      continue
    }
    const withExpected = indexes.map((index) => {
      const expected = items[index]!.arrival.expectedArrival?.trim() ?? ""
      return { index, key: expected ? `${base}|${expected}` : base }
    })
    const expectedCounts = new Map<string, number>()
    for (const entry of withExpected) {
      expectedCounts.set(entry.key, (expectedCounts.get(entry.key) ?? 0) + 1)
    }
    const stillColliding = new Map<string, number>()
    for (const entry of withExpected) {
      if ((expectedCounts.get(entry.key) ?? 0) <= 1) {
        keys[entry.index] = entry.key
        continue
      }
      const next = (stillColliding.get(entry.key) ?? 0) + 1
      stillColliding.set(entry.key, next)
      keys[entry.index] = `${entry.key}#${next}`
    }
  }

  return items.map((item, index) => ({
    key: keys[index]!,
    arrival: item.arrival,
    sourceIndex: item.sourceIndex,
  }))
}

export const arrivalCanonicalLineId = (arrival: RealtimePrediction): string => {
  const tagged = arrival as PredictionWithSharedTrackIdentity
  const identity = tagged.sharedTrackIdentity
  const canonicalLineId =
    identity?.confidence === "exclusive-segment"
      ? identity.canonicalLineId
      : undefined
  return canonicalLineId || arrival.lineId || arrival.lineName || "unknown"
}

const lineKeyOf = (arrival: RealtimePrediction): string =>
  arrivalCanonicalLineId(arrival)

const resolveExpectedBounds = (
  bounds: readonly ArrivalsBoundId[] | undefined
): ArrivalsBoundId[] => {
  if (!bounds?.length) return []
  const seen = new Set<ArrivalsBoundId>()
  const resolved: ArrivalsBoundId[] = []
  for (const value of bounds) {
    const id = normalizeArrivalsBoundId(value)
    if (!id || seen.has(id)) continue
    seen.add(id)
    resolved.push(id)
  }
  return resolved
}

const flattenGroups = (
  groups: readonly ArrivalsPreparedGroup[]
): ArrivalsPreparedRow[] =>
  groups.flatMap((group) => group.bounds.flatMap((bound) => bound.rows))

/**
 * Per-bound / per-route cap. A global walk would spend the budget on the
 * first groups and drop later lines or routes.
 */
const limitRowsPerBound = (
  groups: readonly ArrivalsPreparedGroup[],
  maxRows: number
): ArrivalsPreparedGroup[] =>
  groups.map((group) => {
    const bounds = group.bounds.map((bound) => ({
      ...bound,
      rows: bound.rows.slice(0, maxRows),
    }))
    return {
      ...group,
      bounds,
      hasInformation: bounds.some((bound) => bound.rows.length > 0),
    }
  })

export type ArrivalsPageFill = {
  rows: ArrivalsPreparedRow[]
  /** Quiet dash tiles between the last arrival (or empty row) and the end message. */
  dashCount: number
  /** Final spare tile on a short page that still has arrivals. */
  showEndMessage: boolean
}

export type ArrivalsLockHeight = boolean | "when-paged"

const resolvePageFill = (
  visibleCount: number,
  pageSize: number,
  lockHeight: boolean
): Pick<ArrivalsPageFill, "dashCount" | "showEndMessage"> => {
  if (!lockHeight || pageSize <= 0) {
    return { dashCount: 0, showEndMessage: false }
  }
  if (visibleCount === 0) {
    return { dashCount: Math.max(0, pageSize - 1), showEndMessage: false }
  }
  const spare = pageSize - visibleCount
  if (spare <= 0) {
    return { dashCount: 0, showEndMessage: false }
  }
  return { dashCount: spare - 1, showEndMessage: true }
}

const resolvePageCount = (rowCount: number, pageSize: number): number => {
  if (pageSize <= 0) return 1
  return Math.max(1, Math.ceil(rowCount / pageSize))
}

const shouldLockHeight = (
  lockHeight: ArrivalsLockHeight | undefined,
  pageCount: number
): boolean => {
  if (lockHeight === "when-paged") return pageCount > 1
  return Boolean(lockHeight)
}

/**
 * Visible slice for bound-group pagination. `pageSize <= 0` shows every row.
 * Interactive boards must call this on the live ordered list — do not freeze
 * a snapshot while someone is browsing a later page.
 */
export const sliceBoundPage = (
  rows: readonly ArrivalsPreparedRow[],
  page: number,
  pageSize: number,
  lockHeight: ArrivalsLockHeight = false
): {
  rows: ArrivalsPreparedRow[]
  page: number
  pageCount: number
  dashCount: number
  showEndMessage: boolean
} => {
  const pageCount = resolvePageCount(rows.length, pageSize)
  const locked = shouldLockHeight(lockHeight, pageCount) && pageSize > 0
  if (pageSize <= 0) {
    return {
      rows: [...rows],
      page: 0,
      pageCount: 1,
      dashCount: 0,
      showEndMessage: false,
    }
  }
  const safePage = Math.min(Math.max(0, page), pageCount - 1)
  const start = safePage * pageSize
  const visible = rows.slice(start, start + pageSize)
  return {
    rows: visible,
    page: safePage,
    pageCount,
    ...resolvePageFill(visible.length, pageSize, locked),
  }
}

/** Every page for a scroll-snap track. Reuses `sliceBoundPage` per index. */
export const chunkBoundPages = (
  rows: readonly ArrivalsPreparedRow[],
  pageSize: number,
  options?: { lockHeight?: ArrivalsLockHeight }
): {
  pages: ArrivalsPageFill[]
  pageCount: number
} => {
  const { pageCount } = sliceBoundPage(rows, 0, pageSize, options?.lockHeight)
  return {
    pageCount,
    pages: Array.from({ length: pageCount }, (_, index) => {
      const {
        rows: pageRows,
        dashCount,
        showEndMessage,
      } = sliceBoundPage(rows, index, pageSize, options?.lockHeight)
      return { rows: pageRows, dashCount, showEndMessage }
    }),
  }
}

type LineBucket = {
  lineId: string
  lineIds: string[]
  lineName: string
  modeName?: string
  expectedBounds: ArrivalsBoundId[]
  seededEmpty: boolean
  items: IndexedArrival[]
  firstSourceIndex: number
}

const EMPTY_BOUND = (): ArrivalsPreparedBound => ({
  key: "bound-none",
  label: null,
  kind: "none",
  boundId: null,
  platformLabel: null,
  railDesignation: null,
  platformUniform: false,
  seededEmpty: true,
  rows: [],
})

const orderLineIds = (ids: readonly string[]): string[] =>
  [...ids].sort((a, b) =>
    compareArrivalsLines({ lineId: a, lineName: a }, { lineId: b, lineName: b })
  )

type ResolvedLineGroup = {
  lines: string[]
  label?: string
}

const resolveLineGroups = (
  lineGroups: readonly RailArrivalsLineGroup[] | undefined
): Map<string, ResolvedLineGroup> => {
  const membership = new Map<string, ResolvedLineGroup>()
  for (const raw of lineGroups ?? []) {
    const lines = orderLineIds([
      ...new Set(raw.lines.map((id) => normalizeLineId(id)).filter(Boolean)),
    ])
    if (lines.length < 2) continue
    if (lines.some((id) => membership.has(id))) continue
    const entry: ResolvedLineGroup = { lines, label: raw.label }
    for (const id of lines) membership.set(id, entry)
  }
  return membership
}

const groupBucketKey = (
  lineId: string,
  membership: Map<string, ResolvedLineGroup>
) => {
  const group = membership.get(normalizeLineId(lineId))
  if (!group) return lineId
  return `group:${group.lines.join("+")}`
}

const sharedTrackIdentityRank = (arrival: RealtimePrediction): number => {
  const tagged = arrival as PredictionWithSharedTrackIdentity
  const identity = tagged.sharedTrackIdentity
  if (identity?.confidence === "exclusive-segment") return 0
  if (identity?.confidence === "ambiguous" && identity.rawLineIds.length >= 2) {
    return 1
  }
  return 2
}

/**
 * TfL dual-lists the same vehicle on two lineIds at one shared-track stop.
 * Keep one row per usable `vehicleId` so the board does not paint the same
 * train twice. Placeholder ids stay as separate rows.
 */
const dedupeSharedTrackVehicles = (
  items: readonly IndexedArrival[]
): IndexedArrival[] => {
  const byVehicle = new Map<string, IndexedArrival[]>()
  const passthrough: IndexedArrival[] = []
  for (const item of items) {
    const vehicleId = item.arrival.vehicleId?.trim()
    if (!isUsableVehicleId(vehicleId)) {
      passthrough.push(item)
      continue
    }
    const rows = byVehicle.get(vehicleId)
    if (rows) rows.push(item)
    else byVehicle.set(vehicleId, [item])
  }

  const picked: IndexedArrival[] = []
  for (const rows of byVehicle.values()) {
    if (rows.length === 1) {
      picked.push(rows[0]!)
      continue
    }
    picked.push(
      [...rows].sort((a, b) => {
        const rankDiff =
          sharedTrackIdentityRank(a.arrival) -
          sharedTrackIdentityRank(b.arrival)
        if (rankDiff !== 0) return rankDiff
        const timeDiff =
          (a.arrival.timeToStation ?? 0) - (b.arrival.timeToStation ?? 0)
        if (timeDiff !== 0) return timeDiff
        return a.sourceIndex - b.sourceIndex
      })[0]!
    )
  }

  return [...passthrough, ...picked].sort(
    (a, b) => a.sourceIndex - b.sourceIndex
  )
}

const collectRailLines = (
  indexed: readonly IndexedArrival[],
  expectedLines: readonly RailArrivalsLine[],
  lineGroups?: readonly RailArrivalsLineGroup[]
): LineBucket[] => {
  const membership = resolveLineGroups(lineGroups)
  const byLine = new Map<string, LineBucket>()

  const ensureBucket = (
    key: string,
    init: Omit<LineBucket, "items" | "seededEmpty"> & {
      items?: IndexedArrival[]
      seededEmpty?: boolean
    }
  ): LineBucket => {
    const existing = byLine.get(key)
    if (existing) return existing
    const bucket: LineBucket = {
      lineId: init.lineId,
      lineIds: init.lineIds,
      lineName: init.lineName,
      modeName: init.modeName,
      expectedBounds: init.expectedBounds,
      seededEmpty: init.seededEmpty ?? false,
      items: init.items ?? [],
      firstSourceIndex: init.firstSourceIndex,
    }
    byLine.set(key, bucket)
    return bucket
  }

  for (const item of indexed) {
    const rawId = lineKeyOf(item.arrival)
    const lineId = normalizeLineId(rawId) || rawId
    const key = groupBucketKey(lineId, membership)
    const group = membership.get(normalizeLineId(lineId))
    const existing = byLine.get(key)
    if (existing) {
      existing.items.push(item)
      existing.seededEmpty = false
      existing.firstSourceIndex = Math.min(
        existing.firstSourceIndex,
        item.sourceIndex
      )
      continue
    }
    const lineIds = group?.lines ?? [lineId]
    const names = lineIds.map((id) => getLineNameTiers(id).full)
    ensureBucket(key, {
      lineId: lineIds[0] ?? lineId,
      lineIds,
      lineName:
        group?.label?.trim() ||
        (lineIds.length > 1
          ? joinLineNames(names)
          : getLineNameTiers(lineId, item.arrival.lineName).full || "Unknown"),
      modeName: item.arrival.modeName,
      expectedBounds: [],
      firstSourceIndex: item.sourceIndex,
      items: [item],
    })
  }

  for (const [expectedIndex, expected] of expectedLines.entries()) {
    const expectedId = expected.lineId || expected.lineName
    if (!expectedId) continue
    const lineId = normalizeLineId(expected.lineId) || expectedId
    const key = groupBucketKey(lineId, membership)
    const group = membership.get(normalizeLineId(lineId))
    const bounds = resolveExpectedBounds(expected.bounds)
    const existing = byLine.get(key)
    if (existing) {
      if (bounds.length > 0) {
        const seen = new Set(existing.expectedBounds)
        for (const bound of bounds) {
          if (seen.has(bound)) continue
          seen.add(bound)
          existing.expectedBounds.push(bound)
        }
      }
      continue
    }
    const lineIds = group?.lines ?? [lineId]
    const names = lineIds.map(
      (id) => getLineNameTiers(id, expected.lineName).full
    )
    ensureBucket(key, {
      lineId: lineIds[0] ?? lineId,
      lineIds,
      lineName:
        group?.label?.trim() ||
        (lineIds.length > 1 ? joinLineNames(names) : expected.lineName),
      modeName: expected.modeName,
      expectedBounds: bounds,
      seededEmpty: true,
      items: [],
      firstSourceIndex: indexed.length + expectedIndex,
    })
  }

  for (const bucket of byLine.values()) {
    if (bucket.items.length > 1) {
      bucket.items = dedupeSharedTrackVehicles(bucket.items)
    }
  }

  return [...byLine.values()]
}

type BoundKind = ArrivalsBoundKind

type BoundBucket = {
  kind: BoundKind
  boundId: ArrivalsBoundId | null
  railDesignation: ArrivalsRailDesignation | null
  platformLabels: Set<string>
  items: IndexedArrival[]
  firstSourceIndex: number
}

const classifyArrivalBound = (
  platformName?: string
): {
  kind: Exclude<BoundKind, "none">
  boundId: ArrivalsBoundId | null
  platformLabel: string | null
  railDesignation: ArrivalsRailDesignation | null
} => {
  const boundId = parseCompassBoundId(platformName)
  const platformLabel = parseArrivalsPlatformLabel(platformName)
  const railDesignation = boundId
    ? null
    : parseArrivalsRailDesignation(platformName)
  if (boundId) {
    return { kind: "compass", boundId, platformLabel, railDesignation: null }
  }
  if (platformLabel) {
    return { kind: "platform", boundId: null, platformLabel, railDesignation }
  }
  return {
    kind: "unknown",
    boundId: null,
    platformLabel: null,
    railDesignation: null,
  }
}

const boundBucketKey = (
  kind: BoundKind,
  boundId: ArrivalsBoundId | null,
  platformLabel: string | null,
  railDesignation: ArrivalsRailDesignation | null
): string => {
  if (kind === "compass" && boundId) return `compass:${boundId}`
  if (kind === "platform" && platformLabel) {
    return railDesignation
      ? `platform:${railDesignation}:${platformLabel}`
      : `platform:${platformLabel}`
  }
  if (kind === "unknown") return "unknown"
  return "none"
}

const collectRailBounds = (
  items: readonly IndexedArrival[],
  expectedBounds: readonly ArrivalsBoundId[],
  sortBy: RailArrivalsSortBy,
  boundSortBy: RailArrivalsBoundSortBy
): ArrivalsPreparedBound[] => {
  const byBound = new Map<string, BoundBucket>()

  const ensure = (
    key: string,
    kind: BoundKind,
    boundId: ArrivalsBoundId | null,
    railDesignation: ArrivalsRailDesignation | null,
    sourceIndex: number
  ): BoundBucket => {
    const existing = byBound.get(key)
    if (existing) return existing
    const bucket: BoundBucket = {
      kind,
      boundId,
      railDesignation,
      platformLabels: new Set(),
      items: [],
      firstSourceIndex: sourceIndex,
    }
    byBound.set(key, bucket)
    return bucket
  }

  for (const item of items) {
    const classified = classifyArrivalBound(item.arrival.platformName)
    const key = boundBucketKey(
      classified.kind,
      classified.boundId,
      classified.platformLabel,
      classified.railDesignation
    )
    const bucket = ensure(
      key,
      classified.kind,
      classified.boundId,
      classified.railDesignation,
      item.sourceIndex
    )
    bucket.items.push(item)
    if (classified.platformLabel) {
      bucket.platformLabels.add(classified.platformLabel)
    }
  }

  for (const [boundIndex, boundId] of expectedBounds.entries()) {
    const key = boundBucketKey("compass", boundId, null, null)
    if (byBound.has(key)) continue
    ensure(key, "compass", boundId, null, items.length + boundIndex)
  }

  if (byBound.size === 0) {
    return [EMPTY_BOUND()]
  }

  const sorted = [...byBound.entries()].sort((a, b) => {
    if (boundSortBy === "source") {
      return a[1].firstSourceIndex - b[1].firstSourceIndex
    }
    const aUnknown = a[1].kind === "unknown"
    const bUnknown = b[1].kind === "unknown"
    if (aUnknown !== bUnknown) return aUnknown ? 1 : -1
    const aSort = a[1].boundId ? formatArrivalsBoundLabel(a[1].boundId) : a[0]
    const bSort = b[1].boundId ? formatArrivalsBoundLabel(b[1].boundId) : b[0]
    return compareArrivalsBounds(
      a[1].kind === "compass" ? aSort : a[1].kind === "unknown" ? null : aSort,
      b[1].kind === "compass" ? bSort : b[1].kind === "unknown" ? null : bSort
    )
  })

  return sorted.map(([key, bucket]) => {
    const uniquePlatforms = [...bucket.platformLabels]
    const platformUniform = uniquePlatforms.length === 1
    const platformLabel = platformUniform ? uniquePlatforms[0]! : null
    const hoistPlatform =
      bucket.kind === "platform" ||
      (bucket.kind === "compass" && platformUniform)
    const label = formatBoundHeading({
      boundId: bucket.boundId,
      platformLabel: hoistPlatform ? platformLabel : null,
      railDesignation: bucket.railDesignation,
      unknown: bucket.kind === "unknown",
    })
    return {
      key: `bound-${key}`,
      label,
      kind: bucket.kind,
      boundId: bucket.boundId,
      platformLabel: hoistPlatform ? platformLabel : null,
      railDesignation: bucket.railDesignation,
      platformUniform: hoistPlatform && platformLabel !== null,
      seededEmpty: bucket.items.length === 0,
      rows: assignPreparedRows(sortIndexed(bucket.items, sortBy)),
    }
  })
}

export type PrepareRailArrivalsOptions = {
  data?: readonly RealtimePrediction[]
  lines?: readonly RailArrivalsLine[]
  /**
   * Merge listed line ids into one section. Off by default. Groups with
   * fewer than two ids, or that collide with an earlier group, are ignored.
   */
  lineGroups?: readonly RailArrivalsLineGroup[]
  sortBy?: RailArrivalsSortBy
  lineSortBy?: RailArrivalsLineSortBy
  boundSortBy?: RailArrivalsBoundSortBy
  /**
   * Explicit line section order. Listed lines rank by list position; unlisted
   * lines follow, canonical among themselves. Ordering only — does not seed
   * or hide lines. When set, overrides `lineSortBy`.
   */
  lineOrder?: readonly string[]
  /**
   * Current time (ms) — drops any prediction whose `timeToLive` has already
   * expired (see `isExpiredArrivalPrediction`). Omit to skip this filter,
   * e.g. static demos with no live "now". Live callers should pass
   * `Date.now()` captured alongside `data` at fetch time, not a default
   * evaluated wherever this runs — see
   * `.cursor/rules/nextjs-cache-components-time.mdc`.
   */
  now?: number
  /** Per-bound prediction cap. Does not drop later lines. Default 16. */
  maxRows?: number
}

const lineOrderRank = (
  lineIds: readonly string[],
  order: ReadonlyMap<string, number>
): number | undefined => {
  let best: number | undefined
  for (const lineId of lineIds) {
    const rank = order.get(normalizeLineId(lineId))
    if (rank === undefined) continue
    if (best === undefined || rank < best) best = rank
  }
  return best
}

export const prepareRailArrivals = ({
  data,
  lines = [],
  lineGroups,
  sortBy = "timeToStation",
  lineSortBy = "canonical",
  boundSortBy = "compass",
  lineOrder,
  now,
  maxRows = DEFAULT_MAX_ROWS,
}: PrepareRailArrivalsOptions): ArrivalsPreparedBoard => {
  const indexed = indexArrivals(data).filter(
    (item) =>
      now === undefined || !isExpiredArrivalPrediction(item.arrival, now)
  )
  const buckets = collectRailLines(indexed, lines, lineGroups)

  const explicitOrder =
    lineOrder && lineOrder.length > 0
      ? new Map(
          lineOrder.map((id, index) => [normalizeLineId(id), index] as const)
        )
      : null

  buckets.sort((a, b) => {
    if (explicitOrder) {
      const aRank = lineOrderRank(a.lineIds, explicitOrder)
      const bRank = lineOrderRank(b.lineIds, explicitOrder)
      if (aRank !== undefined && bRank !== undefined) return aRank - bRank
      if (aRank !== undefined) return -1
      if (bRank !== undefined) return 1
      return compareArrivalsLines(
        { lineId: a.lineId, lineName: a.lineName },
        { lineId: b.lineId, lineName: b.lineName }
      )
    }
    if (lineSortBy === "source") {
      return a.firstSourceIndex - b.firstSourceIndex
    }
    return compareArrivalsLines(
      { lineId: a.lineId, lineName: a.lineName },
      { lineId: b.lineId, lineName: b.lineName }
    )
  })

  const groups: ArrivalsPreparedGroup[] = buckets.map((bucket) => {
    const bounds = collectRailBounds(
      bucket.items,
      bucket.expectedBounds,
      sortBy,
      boundSortBy
    )
    const hasInformation = bounds.some((bound) => bound.rows.length > 0)
    return {
      key:
        bucket.lineIds.length > 1
          ? `group:${bucket.lineIds.join("+")}`
          : bucket.lineId || bucket.lineName,
      lineId: bucket.lineId,
      lineIds: bucket.lineIds,
      lineName: bucket.lineName,
      modeName: bucket.modeName,
      kind: "rail-line",
      hasInformation,
      seededEmpty: bucket.seededEmpty,
      bounds,
    }
  })

  const limited = limitRowsPerBound(groups, maxRows)
  return {
    layout: "grouped",
    groups: limited,
    rows: flattenGroups(limited),
  }
}

const collectBusRoutes = (indexed: readonly IndexedArrival[]): LineBucket[] => {
  const byRoute = new Map<string, LineBucket>()

  for (const item of indexed) {
    const key = lineKeyOf(item.arrival)
    const existing = byRoute.get(key)
    if (existing) {
      existing.items.push(item)
      continue
    }
    byRoute.set(key, {
      lineId: item.arrival.lineId ?? "",
      lineIds: [item.arrival.lineId ?? key],
      lineName: (item.arrival.lineName ?? item.arrival.lineId) || "Unknown",
      modeName: item.arrival.modeName,
      expectedBounds: [],
      seededEmpty: false,
      items: [item],
      firstSourceIndex: item.sourceIndex,
    })
  }

  return [...byRoute.values()]
}

export type PrepareBusArrivalsOptions = {
  data?: readonly RealtimePrediction[]
  groupBy?: BusArrivalsGroupBy
  sortBy?: BusArrivalsSortBy
  groupSortBy?: BusArrivalsGroupSortBy
  /**
   * Current time (ms) — drops predictions whose `timeToLive` has already
   * expired. Same rail "self-destination" trap in principle (see
   * `isExpiredArrivalPrediction`); pass `Date.now()` captured alongside
   * `data` at fetch time. Omit to skip this filter.
   */
  now?: number
  maxRows?: number
}

export const prepareBusArrivals = ({
  data,
  groupBy = "none",
  sortBy = "timeToStation",
  groupSortBy = "route",
  now,
  maxRows = DEFAULT_MAX_ROWS,
}: PrepareBusArrivalsOptions): ArrivalsPreparedBoard => {
  const indexed = indexArrivals(data).filter(
    (item) =>
      now === undefined || !isExpiredArrivalPrediction(item.arrival, now)
  )

  if (groupBy !== "route") {
    const rows = assignPreparedRows(
      sortIndexed(indexed, sortBy).slice(0, maxRows)
    )
    return { layout: "flat", groups: [], rows }
  }

  const buckets = collectBusRoutes(indexed)
  buckets.sort((a, b) => {
    if (groupSortBy === "source") {
      return a.firstSourceIndex - b.firstSourceIndex
    }
    return compareBusRouteNames(a.lineName, b.lineName)
  })

  const groups: ArrivalsPreparedGroup[] = buckets.map((bucket) => {
    const rows = assignPreparedRows(sortIndexed(bucket.items, sortBy))
    return {
      key: bucket.lineId || bucket.lineName,
      lineId: bucket.lineId,
      lineIds: bucket.lineIds,
      lineName: bucket.lineName,
      modeName: bucket.modeName,
      kind: "bus-route",
      hasInformation: rows.length > 0,
      seededEmpty: false,
      bounds: [
        {
          key: "bound-none",
          label: null,
          kind: "none",
          boundId: null,
          platformLabel: null,
          railDesignation: null,
          platformUniform: false,
          seededEmpty: rows.length === 0,
          rows,
        },
      ],
    }
  })

  const limited = limitRowsPerBound(groups, maxRows)
  return {
    layout: "grouped",
    groups: limited,
    rows: flattenGroups(limited),
  }
}

/**
 * Shared arrivals board defaults — pure constants, no React.
 * Consumed by the installable board components and the Board URL codec.
 */

/** Visible arrivals per compass bound. Extra trains page behind hover arrows. */
export const RAIL_ARRIVALS_DEFAULT_PAGE_SIZE = 3

/**
 * Shared-platform merges use 2× the single-line default. Collapsing three
 * lines into one section at 3 rows can hide a later train on a different
 * member line; 6 keeps mixed destinations visible without showing all 9.
 */
export const RAIL_ARRIVALS_MERGED_PAGE_SIZE_MULTIPLIER = 2

export const RAIL_ARRIVALS_MERGED_PAGE_SIZE =
  RAIL_ARRIVALS_DEFAULT_PAGE_SIZE * RAIL_ARRIVALS_MERGED_PAGE_SIZE_MULTIPLIER

/** Per-bound prediction cap after ordering. Does not drop later lines. */
export const DEFAULT_MAX_ROWS = 16

/** River waits at this length and above show London clock time, not minutes. */
export const RIVER_COUNTDOWN_CLOCK_FROM_SECONDS = 30 * 60

import { LINE_ORDER, normalizeLineId } from "tfl-ts"

/**
 * Canonical Tube & Rail line rank from `tfl-ts` `LINE_ORDER`.
 * Unknown ids sort after known lines (stable tail).
 */
export const arrivalsLineOrderKey = (lineId: string): number => {
  const index = LINE_ORDER.indexOf(normalizeLineId(lineId))
  return index === -1 ? LINE_ORDER.length : index
}

export type ArrivalsLineSortable = {
  lineId: string
  lineName: string
}

/**
 * Canonical rail line order. Empty lines keep their `LINE_ORDER` slot;
 * this does not move them below live lines, and does not sort by soonest train.
 */
export const compareArrivalsLines = (
  a: ArrivalsLineSortable,
  b: ArrivalsLineSortable
): number => {
  const orderDiff =
    arrivalsLineOrderKey(a.lineId) - arrivalsLineOrderKey(b.lineId)
  if (orderDiff !== 0) return orderDiff

  return a.lineName.localeCompare(b.lineName, "en", {
    numeric: true,
    sensitivity: "base",
  })
}

/**
 * Compass bounds for rail arrivals boards.
 *
 * Vertical lists and LTR tabs share one order: West → East (reading order),
 * North → South (geographic). Omit a bound when arrivals never mention it —
 * unless station metadata seeds that bound via `lines[].bounds`.
 *
 * Bound *headings* are built by `formatBoundHeading` — grouping keys stay
 * compass / platform / unknown, independent of the display string.
 */

import { ARRIVALS_PLATFORM_UNKNOWN_HEADING } from "@/lib/tfl/arrivals-empty"

export const ARRIVALS_BOUND_IDS = [
  "westbound",
  "eastbound",
  "northbound",
  "southbound",
] as const

export type ArrivalsBoundId = (typeof ARRIVALS_BOUND_IDS)[number]

const BOUND_ID_SET = new Set<string>(ARRIVALS_BOUND_IDS)

/** Compass prefix on TfL platform labels, e.g. "Westbound - Platform 1". */
export const COMPASS_BOUND_RE =
  /^(northbound|southbound|eastbound|westbound)\b/i

/**
 * Sub-surface loop wording where compass direction is ambiguous (the shared
 * Circle/Hammersmith & City stretch through Paddington, Bayswater, and
 * Notting Hill Gate — confirmed network-wide, see
 * docs/arrivals-shared-platforms.md). TfL's own boards use this instead of a
 * compass bound: "Inner Rail - Platform 1" / "Outer Rail - Platform 2".
 */
export const RAIL_DESIGNATION_RE = /^(inner|outer)\s+rail\b/i

export type ArrivalsRailDesignation = "inner" | "outer"

export const parseArrivalsRailDesignation = (
  platformName?: string
): ArrivalsRailDesignation | null => {
  if (!platformName) return null
  const match = platformName.match(RAIL_DESIGNATION_RE)
  return (
    (match?.[1]?.toLowerCase() as ArrivalsRailDesignation | undefined) ?? null
  )
}

/** A bare platform letter/number token, e.g. "1", "12", "A" — not a phrase. */
const BARE_PLATFORM_TOKEN_RE = /^[a-z0-9]{1,3}$/i
/** Pulls the number/letter out of a "... Platform N" phrase anywhere in the string. */
const PLATFORM_WORD_TOKEN_RE = /\bplatform\s+([a-z0-9]+)/i

/**
 * Cleaned platform letter or number from a TfL `platformName`, for the
 * compact per-row platform chip. Drops compass/rail-designation prefixes and
 * the literal "Unknown". Descriptive-only labels with no platform number
 * (e.g. Chesham's "North / South") return null — there's nothing short
 * enough for a chip; `formatBoundHeading` still shows the full text.
 */
export const parseArrivalsPlatformLabel = (
  platformName?: string
): string | null => {
  if (!platformName) return null
  if (/\bunknown\b/i.test(platformName)) return null
  const withoutBound = platformName
    .replace(COMPASS_BOUND_RE, "")
    .replace(RAIL_DESIGNATION_RE, "")
    .trim()
  const wordToken = withoutBound.match(PLATFORM_WORD_TOKEN_RE)?.[1]
  if (wordToken) return wordToken
  const bareToken = withoutBound.replace(/^\s*[-–—:]\s*/, "").trim()
  return BARE_PLATFORM_TOKEN_RE.test(bareToken) ? bareToken : null
}

export const normalizeArrivalsBoundId = (
  value: string
): ArrivalsBoundId | null => {
  const id = value.trim().toLowerCase()
  return BOUND_ID_SET.has(id) ? (id as ArrivalsBoundId) : null
}

/** Display label: `westbound` → `Westbound`. */
export const formatArrivalsBoundLabel = (id: ArrivalsBoundId): string =>
  id.charAt(0).toUpperCase() + id.slice(1)

export const parseCompassBoundId = (
  platformName?: string
): ArrivalsBoundId | null => {
  if (!platformName) return null
  const match = platformName.match(COMPASS_BOUND_RE)
  if (!match?.[1]) return null
  return normalizeArrivalsBoundId(match[1])
}

/** True for TfL's literal "Platform Unknown" (and close variants). */
export const isUnknownArrivalsPlatform = (platformName?: string): boolean =>
  Boolean(platformName && /\bunknown\b/i.test(platformName))

/** Display label for a rail designation: `inner` → `Inner Rail`. */
export const formatArrivalsRailDesignationLabel = (
  designation: ArrivalsRailDesignation
): string => (designation === "inner" ? "Inner Rail" : "Outer Rail")

/** Heading for a platform-only subgroup: `A` → `Platform A`. */
export const formatPlatformHeading = (platformLabel: string): string =>
  `Platform ${platformLabel}`

export type FormatBoundHeadingInput = {
  boundId?: ArrivalsBoundId | null
  /** Cleaned platform letter/number, when it belongs in the heading. */
  platformLabel?: string | null
  /** Inner/Outer Rail qualifier, when the platform carries one. */
  railDesignation?: ArrivalsRailDesignation | null
  /** Live predictions with unknown/missing platform. */
  unknown?: boolean
}

/**
 * Subgroup heading. Isolated so a future `boundHeadingFormat` prop is a
 * small diff — this default is direction + platform when both exist.
 *
 * - `"Eastbound · Platform 1"`
 * - `"Inner Rail · Platform 1"`
 * - `"Platform A"`
 * - `"Westbound"` (seeded empty bound, or platforms vary inside the bound)
 * - `"Platform to be confirmed"`
 */
export const formatBoundHeading = ({
  boundId,
  platformLabel,
  railDesignation,
  unknown = false,
}: FormatBoundHeadingInput): string | null => {
  if (unknown) return ARRIVALS_PLATFORM_UNKNOWN_HEADING
  const direction = boundId
    ? formatArrivalsBoundLabel(boundId)
    : railDesignation
      ? formatArrivalsRailDesignationLabel(railDesignation)
      : null
  const platform = platformLabel ? formatPlatformHeading(platformLabel) : null
  if (direction && platform) return `${direction} · ${platform}`
  return direction ?? platform
}

export const arrivalsBoundOrderKey = (labelOrId: string | null): number => {
  if (!labelOrId) return ARRIVALS_BOUND_IDS.length + 1
  const id = normalizeArrivalsBoundId(labelOrId)
  if (!id) return ARRIVALS_BOUND_IDS.length
  return ARRIVALS_BOUND_IDS.indexOf(id)
}

export const compareArrivalsBounds = (
  a: string | null,
  b: string | null
): number => arrivalsBoundOrderKey(a) - arrivalsBoundOrderKey(b)

/**
 * Why an arrivals board has no rows. Callers resolve this from fetch result +
 * clock; the board only paints the copy.
 */
export type ArrivalsEmptyKind = "empty" | "ended" | "offline"

export const ARRIVALS_EMPTY_COPY: Record<ArrivalsEmptyKind, string> = {
  empty: "No arrivals right now.",
  ended: "Service has ended for tonight.",
  offline: "You're offline. Arrivals will update when you're back.",
}

/**
 * River predictions can be `[]` while line status is still Good Service
 * (RB4 / Woolwich Ferry). Do not claim that no boats are due.
 */
export const RIVER_ARRIVALS_EMPTY_COPY = "No live departure times available."

/** Per-line / per-route when predictions are missing but the line is still shown. */
export const ARRIVALS_LINE_EMPTY_COPY = "No information"

/** Last spare tile on a short page that still has arrivals. */
export const ARRIVALS_END_COPY = "No more arrivals"

/** Narrow-width step of `ARRIVALS_END_COPY`. Accessible name stays the full phrase. */
export const ARRIVALS_END_COPY_SHORT = "No more"

/**
 * Subgroup heading when TfL sends `Platform Unknown` (or no platform at all)
 * on a live prediction. Distinct from a bound with no heading — that is
 * reserved for true “no bound metadata” (bus lists, empty unseeded lines).
 */
export const ARRIVALS_PLATFORM_UNKNOWN_HEADING = "Platform to be confirmed"

const LONDON_TIME_ZONE = "Europe/London"

const londonHourFormatter = new Intl.DateTimeFormat("en-GB", {
  timeZone: LONDON_TIME_ZONE,
  hour: "2-digit",
  hourCycle: "h23",
})

/** Europe/London hour (0–23) for an instant. Pass `nowMs` — never default the clock here. */
export const londonHour = (nowMs: number): number => {
  const hour = londonHourFormatter
    .formatToParts(new Date(nowMs))
    .find((part) => part.type === "hour")?.value
  return hour ? Number(hour) : 0
}

/**
 * Rough Underground closed window in London local time. Night buses still run,
 * so prefer `empty` for bus boards unless the caller forces `ended`.
 */
export const isLikelyRailServiceEnded = (nowMs: number): boolean => {
  const hour = londonHour(nowMs)
  return hour >= 1 && hour < 5
}

type ResolveArrivalsEmptyKindOptions = {
  rowCount: number
  /** Fetch/render failure — board uses `error` instead. */
  hasError?: boolean
  offline?: boolean
  /** Rail uses the overnight `ended` heuristic; bus and river do not. */
  domain?: "rail" | "bus" | "river"
  nowMs: number
}

/**
 * Pick an empty kind when there are no rows. Returns `null` when the board
 * should show arrivals or an error instead.
 */
export const resolveArrivalsEmptyKind = ({
  rowCount,
  hasError = false,
  offline = false,
  domain = "rail",
  nowMs,
}: ResolveArrivalsEmptyKindOptions): ArrivalsEmptyKind | null => {
  if (hasError || rowCount > 0) return null
  if (offline) return "offline"
  if (domain === "rail" && isLikelyRailServiceEnded(nowMs)) return "ended"
  return "empty"
}

/**
 * Painted bus stop letters — the red circle on a flag / arrivals header.
 *
 * Probed 2026-08-15 (Wapping, The Highway, Trafalgar Square, Oxford Circus,
 * Liverpool Street):
 * - Real letters are 1–2 A–Z (`E`, `RG`, `CV`). Never invent from the name.
 * - NaPTAN suffix is not the letter (`490000251W` is Stop R, not W).
 * - `->W` / `->E` are compass markers on stops with no painted letter.
 * - Search hits are thin (id / name / towards). Letter lives on
 *   `stopPoint.get` / `getByGeoPoint`, or as `platformName` on arrivals.
 */

const PAINTED_STOP_LETTER = /^[A-Z]{1,2}$/

/** TfL sometimes sends the literal string `"null"` instead of omitting a field. */
export const usableTflText = (value?: string | null): string | undefined => {
  const trimmed = value?.trim()
  if (!trimmed || /^(null|undefined)$/i.test(trimmed)) return undefined
  return trimmed
}

/** `Stop RG` / `rg` / `E` → `RG` / `E`. Arrows and stands → undefined. */
export const normaliseBusStopLetter = (
  raw?: string | null
): string | undefined => {
  const stripped = raw
    ?.replace(/^stop\s+/i, "")
    .trim()
    .toUpperCase()
  if (!stripped || !PAINTED_STOP_LETTER.test(stripped)) return undefined
  return stripped
}

export const readStopLetter = (
  stopLetter?: string | null,
  indicator?: string | null
): string | undefined =>
  normaliseBusStopLetter(stopLetter) ?? normaliseBusStopLetter(indicator)

export const getBusStopLetterFromPlatform = (
  platformName?: string | null
): string | null => normaliseBusStopLetter(platformName) ?? null

export const resolveBusStopLetter = (
  stopLetter: string | undefined,
  rows: readonly { platformName?: string }[]
): string | null => {
  const fromProp = normaliseBusStopLetter(stopLetter)
  if (fromProp) return fromProp
  for (const row of rows) {
    const letter = getBusStopLetterFromPlatform(row.platformName)
    if (letter) return letter
  }
  return null
}

/**
 * Chip labels keep normal casing (e.g. “Platform 4”, “Plat 4”).
 * Put this on the painted text node, not the flex chrome — then `items-center`
 * on the chip centres the cap-height box (uppercase X), not the em-square.
 * Chips never show descenders (g/y/p/q), so cap→alphabetic is the optical
 * vertical centre. Do not use x-height (`ex`) trim.
 */
export const CHIP_CAP_TEXT_BOX_CLASS =
  "leading-none [text-box:trim-both_cap_alphabetic]"

/**
 * Shared identity-chip width. Bus routes are ≤4 characters; line codes are
 * 3 letters. One extra `ch` keeps MET / H&C / N253 from clipping.
 */
export const ARRIVALS_IDENTITY_CHIP_WIDTH_CLASS = "w-[5ch]"

/** Unattended rank chip — digit + ordinal suffix (`1st`). */
export const ARRIVALS_RANK_CHIP_WIDTH_CLASS = "w-[3ch]"

export const arrivalsOrdinalSuffix = (
  rank: number
): "st" | "nd" | "rd" | "th" => {
  const abs = Math.abs(Math.trunc(rank))
  const mod100 = abs % 100
  if (mod100 >= 11 && mod100 <= 13) return "th"
  switch (abs % 10) {
    case 1:
      return "st"
    case 2:
      return "nd"
    case 3:
      return "rd"
    default:
      return "th"
  }
}

export const formatArrivalsRankLabel = (rank: number): string =>
  `${rank}${arrivalsOrdinalSuffix(rank)}`

"use client"

import {
  createContext,
  useContext,
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type Dispatch,
  type ReactNode,
  type SetStateAction,
} from "react"
import { BusNumberChip } from "@/components/tfl/arrivals/bus-number-chip"
import { RiverRouteChip } from "@/components/tfl/arrivals/river-route-chip"
import type { BusStopDisruption } from "@/lib/tfl/prepare-bus-stop-disruptions"
import { riverRouteChipCopy } from "@/lib/tfl/river-bus"
import { cn } from "@/lib/utils"

export type StopDisruptionChipVariant = "bus" | "river"

/**
 * Warning-badge colour for disrupted routes. Not a published TfL Colour
 * Standard entry (there is no official "warning" swatch) — chosen to read
 * as hazard/caution signage (dark ink on amber), distinct from any line or
 * modal brand colour so it never gets mistaken for real line identity.
 */
const BUS_DISRUPTION_WARNING_COLOR = "#F5A300"
const BUS_DISRUPTION_WARNING_INK = "#3A2600"

const TRIGGER_SLOT = "bus-stop-disruption-trigger"

type DisruptionContextValue = {
  disruptions: readonly BusStopDisruption[]
  variant: StopDisruptionChipVariant
  activeLineId: string | null
  setActiveLineId: Dispatch<SetStateAction<string | null>>
}

const DisruptionContext = createContext<DisruptionContextValue | null>(null)

/**
 * Client boundary shared by the header's warning chips and the cover below
 * them. `relative` is the positioning root the cover pins to — it spans
 * header + rows, and the cover's own `top` skips exactly one
 * `--arrivals-row` (the header tile) so it only ever masks the prediction
 * rows, never the chips that opened it.
 *
 * No-ops (renders `children` untouched) when there is nothing to warn about.
 */
export const BusStopDisruptionBoundary = ({
  disruptions,
  variant = "bus",
  children,
}: {
  disruptions: readonly BusStopDisruption[]
  variant?: StopDisruptionChipVariant
  children: ReactNode
}) => {
  const [activeLineId, setActiveLineId] = useState<string | null>(null)

  if (disruptions.length === 0) {
    return <>{children}</>
  }

  return (
    <DisruptionContext.Provider
      value={{ disruptions, variant, activeLineId, setActiveLineId }}
    >
      <div className="relative">{children}</div>
    </DisruptionContext.Provider>
  )
}

/**
 * Badge geometry per chip size — cutout is deliberately larger than the
 * badge. `insetX` / `insetY` pull the badge (and its matching cutout) in
 * from the exact corner so it reads as sitting on the chip rather than
 * mostly hanging off it.
 */
const BADGE_GEOMETRY = {
  sm: {
    badge: 14,
    cutout: 9,
    insetX: 0,
    insetY: 3,
    stroke: [2, 6] as const,
    dot: 2,
    gap: 1.5,
  },
  lg: {
    badge: 20,
    cutout: 13,
    insetX: 0,
    insetY: 4,
    stroke: [2.5, 8] as const,
    dot: 2.5,
    gap: 2,
  },
}

/**
 * Corner mask on the chip itself — a true transparent cutout (not a
 * same-colour ring standing in for a border), centred to match the badge's
 * (inset) position. Whatever sits behind the chip shows through the gap
 * untouched, regardless of the surrounding background.
 */
const cutoutMaskStyle = (
  radiusPx: number,
  insetXPx: number,
  insetYPx: number
): CSSProperties => {
  const mask = `radial-gradient(circle at calc(100% - ${insetXPx}px) ${insetYPx}px, transparent ${radiusPx - 1}px, black ${radiusPx}px)`
  return {
    WebkitMaskImage: mask,
    maskImage: mask,
    WebkitMaskRepeat: "no-repeat",
    maskRepeat: "no-repeat",
  }
}

/** Custom-drawn "!" — a distinct stroke and dot, legible at badge scale where the glyph blurs into one shape. */
const WarningMark = ({
  stroke,
  dot,
  gap,
}: {
  stroke: readonly [number, number]
  dot: number
  gap: number
}) => (
  <span
    className="flex flex-col items-center justify-center"
    style={{ gap }}
    aria-hidden
  >
    <span
      className="rounded-full"
      style={{
        width: stroke[0],
        height: stroke[1],
        backgroundColor: BUS_DISRUPTION_WARNING_INK,
      }}
    />
    <span
      className="rounded-full"
      style={{
        width: dot,
        height: dot,
        backgroundColor: BUS_DISRUPTION_WARNING_INK,
      }}
    />
  </span>
)

/** Route chip with a masked-through warning badge pinned to its top-right corner. */
const DisruptedRouteChip = ({
  lineId,
  variant,
  size = "sm",
  chipClassName,
}: {
  lineId: string
  variant: StopDisruptionChipVariant
  size?: "sm" | "lg"
  chipClassName?: string
}) => {
  const geometry = BADGE_GEOMETRY[size]
  const mask = cutoutMaskStyle(
    geometry.cutout,
    geometry.insetX,
    geometry.insetY
  )
  return (
    <span className="relative inline-flex shrink-0 overflow-visible">
      {variant === "river" ? (
        <RiverRouteChip
          lineId={lineId}
          className={chipClassName}
          style={mask}
        />
      ) : (
        <BusNumberChip label={lineId} className={chipClassName} style={mask} />
      )}
      <span
        className="absolute flex items-center justify-center rounded-full"
        style={{
          top: geometry.insetY - geometry.badge / 2,
          right: geometry.insetX - geometry.badge / 2,
          width: geometry.badge,
          height: geometry.badge,
          backgroundColor: BUS_DISRUPTION_WARNING_COLOR,
        }}
      >
        <WarningMark
          stroke={geometry.stroke}
          dot={geometry.dot}
          gap={geometry.gap}
        />
      </span>
    </span>
  )
}

const disruptionTriggerLabel = (
  variant: StopDisruptionChipVariant,
  lineId: string,
  description: string
): string => {
  const identity =
    variant === "river"
      ? riverRouteChipCopy(lineId).ariaLabel
      : `Route ${lineId}`
  return `${identity} disruption: ${description}`
}

/**
 * Header trigger row — one warning chip per disrupted route, painted
 * inline after the stop name. Mouse hover opens; tap/`click` toggles.
 * Hover is `pointerType === "mouse"` only — touch also synthesises
 * `mouseenter` then `click` in one gesture, and the click would toggle
 * the cover straight back shut. Any other chip dims to `opacity-50`
 * while one is active so the open one reads as selected.
 *
 * Triggers sit on the title baseline, immediately after the name.
 * Neighbours share a zero-gap hit strip (padding is inside each button)
 * so the pointer never crosses a dead zone that would blink the cover
 * closed. Painted chip stays `h-5` / `text-xs` / `5ch`.
 */
export const BusStopDisruptionChips = ({
  className,
}: {
  className?: string
}) => {
  const ctx = useContext(DisruptionContext)
  if (!ctx || ctx.disruptions.length === 0) return null
  const { disruptions, variant, activeLineId, setActiveLineId } = ctx

  return (
    <div className={cn("flex shrink-0 items-center pr-2", className)}>
      {disruptions.map((disruption) => {
        const isActive = activeLineId === disruption.lineId
        const isDimmed = activeLineId !== null && !isActive
        return (
          <button
            key={disruption.lineId}
            type="button"
            data-slot={TRIGGER_SLOT}
            className={cn(
              "flex shrink-0 items-center justify-center px-1.5 transition-opacity first:pl-1",
              isDimmed && "opacity-50"
            )}
            aria-expanded={isActive}
            aria-label={disruptionTriggerLabel(
              variant,
              disruption.lineId,
              disruption.description
            )}
            onPointerEnter={(event) => {
              if (event.pointerType !== "mouse") return
              setActiveLineId(disruption.lineId)
            }}
            onPointerLeave={(event) => {
              if (event.pointerType !== "mouse") return
              setActiveLineId((current) =>
                current === disruption.lineId ? null : current
              )
            }}
            onClick={() =>
              setActiveLineId((current) =>
                current === disruption.lineId ? null : disruption.lineId
              )
            }
          >
            <DisruptedRouteChip
              lineId={disruption.lineId}
              variant={variant}
              size="sm"
            />
          </button>
        )
      })}
    </div>
  )
}

/**
 * Cover over the prediction rows for the active disruption — the larger
 * chip inline with its full description text. A solid surface a shade
 * darker than the page background (not a translucent copy of it) so the
 * cover reads as its own panel. Tapping/clicking anywhere outside the
 * cover and the trigger row closes it.
 */
export const BusStopDisruptionCover = () => {
  const ctx = useContext(DisruptionContext)
  const coverRef = useRef<HTMLDivElement>(null)
  const active =
    ctx?.disruptions.find((d) => d.lineId === ctx.activeLineId) ?? null

  useEffect(() => {
    if (!ctx || !active) return
    const handlePointerDown = (event: PointerEvent) => {
      const target = event.target as Element | null
      if (coverRef.current?.contains(target)) return
      if (target?.closest(`[data-slot="${TRIGGER_SLOT}"]`)) return
      ctx.setActiveLineId(null)
    }
    document.addEventListener("pointerdown", handlePointerDown)
    return () => document.removeEventListener("pointerdown", handlePointerDown)
  }, [ctx, active])

  if (!ctx || !active) return null

  return (
    <div
      ref={coverRef}
      className="absolute inset-x-0 top-[var(--arrivals-row)] bottom-0 z-10 flex items-start bg-muted p-3"
      role="status"
    >
      <p className="flex flex-wrap items-center gap-x-2.5 gap-y-1 text-base text-pretty text-foreground">
        <DisruptedRouteChip
          lineId={active.lineId}
          variant={ctx.variant}
          size="lg"
          chipClassName="h-8 w-[6ch] text-base"
        />
        {active.description}
      </p>
    </div>
  )
}

/**
 * Minimal shape of `client.stopPoint.getDisruption` / `getDisruptionByMode`
 * results. Kept decoupled from `tfl-ts`'s generated type so this file (and
 * its tests) don't need the SDK to construct fixtures.
 */
export type RawBusStopDisruption = {
  description?: string
  concernedLines?: readonly { id?: string }[]
}

export type BusStopDisruption = {
  /** Route code as painted on `BusNumberChip` (e.g. `"158"`). */
  lineId: string
  /** Human-readable disruption text, cleaned of embedded newlines. */
  description: string
}

const ROUTE_MENTION = /route\s+([a-z0-9]{1,4})\b/i
const RIVER_LINE_MENTION = /\b(rb[146]|woolwich[\s-]?ferry)\b/i

/**
 * Keep bus route codes as TfL painted them (`N22`). Canonicalise river ids
 * so `RB1` / `Woolwich Ferry` match `isRiverBusLineId` and the river chip.
 */
const normaliseDisruptionLineId = (raw: string): string => {
  const trimmed = raw.trim()
  const id = trimmed.toLowerCase()
  if (/^woolwich[\s-]?ferry$/.test(id) || id === "wf") return "woolwich-ferry"
  if (/^rb[146]$/.test(id)) return id
  return trimmed
}

/**
 * TfL's free-text disruption copy wraps lines with a literal `\n` — two
 * plain characters (backslash + "n"), not a real newline — plus occasional
 * real whitespace. Collapse both into single spaces.
 */
const cleanDescription = (raw: string | undefined): string =>
  (raw ?? "").replace(/\\+n/g, " ").replace(/\s+/g, " ").trim()

/**
 * Normalise stop-point disruptions into per-route warnings a bus board can
 * paint. Empirically (checked against live TfL data), `concernedLines` is
 * almost never populated for bus closures — the affected route, when named
 * at all, only appears in the free-text `description` (e.g. "Route 164 is
 * on diversion…"). Two real shapes follow from that:
 *
 * - Route-specific: attach the warning to that one route, even when `rows`
 *   has zero arrivals for it. A diverted route often vanishes from
 *   predictions entirely at this stop — that disappearance is exactly what
 *   is worth flagging, not just routes still visibly running.
 * - Stop-wide ("Bus Stop Closed", no route named): the whole physical stop
 *   is affected, so the same text applies to every route currently in
 *   `rows` — no route there is more or less affected than another.
 *
 * River piers use the same `DisruptedPoint` payload. Mentions look like
 * `RB1` or `Woolwich Ferry` rather than `Route 164`; a pier-wide closure
 * still fans out to every river route in `rows`.
 */
export const prepareBusStopDisruptions = (
  disruptions: readonly RawBusStopDisruption[],
  rows: readonly { lineName?: string }[]
): readonly BusStopDisruption[] => {
  const knownRoutes = [
    ...new Set(
      rows
        .map((row) => row.lineName?.trim())
        .filter((name): name is string => Boolean(name))
    ),
  ]

  const byLineId = new Map<string, string>()

  for (const disruption of disruptions) {
    const description = cleanDescription(disruption.description)
    if (!description) continue

    const concerned = (disruption.concernedLines ?? [])
      .map((line) => line.id?.trim())
      .filter((id): id is string => Boolean(id))

    const mentioned =
      description.match(ROUTE_MENTION)?.[1] ??
      description.match(RIVER_LINE_MENTION)?.[1]

    const lineIds = (
      concerned.length > 0 ? concerned : mentioned ? [mentioned] : knownRoutes
    ).map(normaliseDisruptionLineId)

    for (const lineId of lineIds) {
      if (!byLineId.has(lineId)) byLineId.set(lineId, description)
    }
  }

  return [...byLineId.entries()].map(([lineId, description]) => ({
    lineId,
    description,
  }))
}

"use client"

import {
  Fragment,
  useEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react"
import { cn } from "@/lib/utils"
import { FindableText } from "@/components/tfl/findable-text"
import {
  approximateStationMeasure,
  createCanvasStationMeasure,
  formatStationLabel,
  resolveSansFontFamily,
  type StationLabelFormatResult,
} from "@/lib/tfl/station-typography"
import { formatStationName } from "@/lib/tfl/diagram-station"
import {
  findCompletionForToken,
  stationCopyName,
  stationFindAliases,
  stationFindCoveredPhrases,
} from "@/lib/tfl/station-label-find"

export type StationNameLayout = "fixed" | "auto"

export type StationNameProps = {
  name: string
  className?: string
  style?: CSSProperties
  /**
   * Explicit visual lines (editorial / crowding recipes).
   * When set, skips auto word-break selection.
   */
  lines?: readonly string[]
  /**
   * `fixed` (default): use `lines` or a single canonical line — no measure/scale.
   * `auto`: measure the box and pick 1–2 lines / abbr / scale via formatStationLabel.
   */
  layout?: StationNameLayout
  /**
   * When set with `layout="auto"`, labels measure against this width instead
   * of the container. Useful for fixed diagram columns.
   */
  maxWidth?: number
  fontSize?: number
  maxLines?: 1 | 2
  allowAbbreviation?: boolean
  allowScaleDown?: boolean
  minScale?: number
  /**
   * @deprecated Prefer `lines`. Kept for call-site compatibility.
   */
  forcedLines?: readonly string[]
  /**
   * Canonical single-line name for aria + copy. Defaults to `formatStationName`.
   */
  accessibleName?: string
  /**
   * @deprecated No longer required — find/copy/aria always use the canonical name.
   */
  abbreviatedVisual?: boolean
  /** Align text within the label block. */
  align?: "left" | "center" | "right"
  /** Expose format diagnostics to a parent (typography lab). */
  onFormat?: (result: StationLabelFormatResult) => void
}

/** @deprecated Use `StationNameProps`. */
export type StationNameLabelProps = StationNameProps

type SizeState = {
  width: number
  fontSize: number
  fontFamily: string
  measured: boolean
}

const WIDTH_EPSILON = 0.5
const FONT_EPSILON = 0.05
const FALLBACK_FONT = "Hammersmith One, system-ui, sans-serif"
/** Unitless so wrapped lines stay clustered when `scale` shrinks font-size. */
const MULTILINE_LINE_HEIGHT = 1.15

/**
 * Invisible inline completion (e.g. St + "reet" → Street) for engines that
 * still index font-size: 0. Primary cross-line find uses FindPhrase below.
 */
const FindExpand = ({ text }: { text: string }) => (
  <span className="text-[0px] leading-none" aria-hidden="true">
    {text}
  </span>
)

const renderFindableLine = (line: string): ReactNode[] =>
  line.split(/(\s+|&)/).map((part, index) => {
    if (!part) return null
    const completion = findCompletionForToken(part)
    if (!completion) {
      return <Fragment key={`${part}-${index}`}>{part}</Fragment>
    }
    return (
      <Fragment key={`${part}-${index}`}>
        {part}
        <FindExpand text={completion} />
      </Fragment>
    )
  })

const fixedResult = (
  name: string,
  lines?: readonly string[]
): StationLabelFormatResult => {
  const displayName = formatStationName(name)
  if (lines && lines.length > 0) {
    return {
      lines: [...lines],
      scale: 1,
      abbreviated: lines.join(" ") !== displayName,
      fits: true,
      displayName,
    }
  }
  return {
    lines: [displayName],
    scale: 1,
    abbreviated: false,
    fits: true,
    displayName,
  }
}

/**
 * Station name UI contract: canonical copy / aria, find-in-page variants,
 * and optional visual line breaks. String-driven so non-TfL labels (pubs,
 * attractions) can use the same find/copy behaviour.
 *
 * Diagrams typically pass `lines` from a label recipe with `layout="fixed"`.
 * The typography lab uses `layout="auto"` + `maxWidth` to exercise fit policy.
 */
export const StationName = ({
  name,
  className,
  style,
  lines: linesProp,
  layout = "fixed",
  maxWidth: maxWidthProp,
  fontSize: fontSizeProp,
  maxLines = 2,
  allowAbbreviation = false,
  allowScaleDown = true,
  minScale,
  forcedLines,
  accessibleName: accessibleNameProp,
  align = "left",
  onFormat,
}: StationNameProps) => {
  const ref = useRef<HTMLSpanElement>(null)
  const visualLines = linesProp ?? forcedLines
  const useAuto = layout === "auto"
  const hasFixedMetrics =
    useAuto && maxWidthProp != null && maxWidthProp > 0 && fontSizeProp != null
  const copyName = stationCopyName(name, accessibleNameProp)

  const [size, setSize] = useState<SizeState>(() => ({
    width: maxWidthProp ?? 0,
    fontSize: fontSizeProp ?? 16,
    fontFamily: FALLBACK_FONT,
    measured: false,
  }))

  useEffect(() => {
    if (!useAuto) return
    const el = ref.current
    if (!el) return

    let cancelled = false
    const container = el.parentElement

    const readMetrics = () => {
      if (cancelled) return

      const width =
        maxWidthProp ??
        (container && container.clientWidth > 0
          ? container.clientWidth
          : el.clientWidth)

      const measuredFont =
        fontSizeProp ?? (Number.parseFloat(getComputedStyle(el).fontSize) || 16)
      const fontFamily = resolveSansFontFamily(el)

      setSize((prev) => {
        if (
          prev.measured &&
          Math.abs(prev.width - width) < WIDTH_EPSILON &&
          Math.abs(prev.fontSize - measuredFont) < FONT_EPSILON &&
          prev.fontFamily === fontFamily
        ) {
          return prev
        }
        return {
          width,
          fontSize: measuredFont,
          fontFamily,
          measured: true,
        }
      })
    }

    const waitFonts = async () => {
      try {
        if (document.fonts?.ready) await document.fonts.ready
      } catch {
        // Ignore font loading errors; approximate measure still works.
      }
      readMetrics()
    }

    void waitFonts()

    const observer = new ResizeObserver(() => readMetrics())
    if (container) observer.observe(container)
    else observer.observe(el)

    return () => {
      cancelled = true
      observer.disconnect()
    }
  }, [fontSizeProp, maxWidthProp, name, useAuto])

  const measure = useMemo(() => {
    if (!useAuto || !size.measured) return approximateStationMeasure
    return createCanvasStationMeasure(size.fontFamily)
  }, [size.fontFamily, size.measured, useAuto])

  const formatOptions = useMemo(
    () => ({
      maxWidth: Math.max(size.width, 1),
      fontSize: size.fontSize,
      maxLines,
      allowAbbreviation,
      allowScaleDown,
      minScale,
      forcedLines: visualLines,
    }),
    [
      allowAbbreviation,
      allowScaleDown,
      visualLines,
      maxLines,
      minScale,
      size.fontSize,
      size.width,
    ]
  )

  const result = useMemo(() => {
    if (!useAuto) return fixedResult(name, visualLines)

    // Unmeasured (or a ~0px slot) stays at full size. Pretending the box is
    // 1px wide forced minScale on every first paint, then a shrink-wrapped
    // parent ratcheted that small size even when the heading had room.
    // Tiles clip overflow; scale down only after a real slot width exists.
    if (!hasFixedMetrics && (!size.measured || size.width <= 4)) {
      return fixedResult(name, visualLines)
    }
    return formatStationLabel(name, measure, formatOptions)
  }, [
    formatOptions,
    hasFixedMetrics,
    measure,
    name,
    size.measured,
    size.width,
    useAuto,
    visualLines,
  ])

  useEffect(() => {
    if (!useAuto) {
      onFormat?.(result)
      return
    }
    if (!size.measured || size.width <= 0) return
    onFormat?.(result)
  }, [onFormat, result, size.measured, size.width, useAuto])

  const coveredPhrases = useMemo(
    () => stationFindCoveredPhrases(result.lines),
    [result.lines]
  )
  const findAliases = useMemo(
    () => stationFindAliases(copyName, result.lines),
    [copyName, result.lines]
  )

  const textAlign =
    align === "center" ? "center" : align === "right" ? "right" : "left"
  const multiline = result.lines.length > 1

  const paintDiffersFromCopy =
    multiline ||
    result.abbreviated ||
    result.lines.join(" ").replace(/\s+/g, " ").trim() !== copyName
  const extraFindAliases = findAliases.filter(
    (alias) => alias.toLowerCase() !== copyName.toLowerCase()
  )

  return (
    <FindableText
      ref={ref}
      text={copyName}
      aliases={extraFindAliases}
      coveredPhrases={coveredPhrases}
      paintMatchesText={!paintDiffersFromCopy}
      className={cn(
        "relative inline-flex h-full min-h-0 w-full min-w-0 flex-col justify-center",
        useAuto && maxWidthProp == null && "flex-1",
        !multiline && "leading-none",
        align === "center" && "items-center",
        align === "right" && "items-end",
        align === "left" && "items-start",
        className
      )}
      style={{
        ...style,
        fontSize: fontSizeProp != null ? `${fontSizeProp}px` : style?.fontSize,
        textAlign,
      }}
    >
      <span
        className="inline-block w-full min-w-0"
        style={{
          fontSize: result.scale !== 1 ? `${result.scale * 100}%` : undefined,
          // Unitless LH tracks scaled font-size; rem leading from callers would not.
          lineHeight: multiline ? MULTILINE_LINE_HEIGHT : undefined,
        }}
        aria-hidden="true"
        // `layout="auto"` intentionally repaints once the box is measured
        // (approximate → canvas fit can pick a different line break/scale
        // than the pre-measure guess). That's a post-hydration update, not a
        // markup mismatch, but suppress the warning on this node only —
        // never on the whole component — since the two passes can render
        // different characters/line breaks for the same props.
        suppressHydrationWarning={useAuto}
      >
        {result.lines.map((line, index) => (
          <Fragment key={`${line}-${index}`}>
            {index > 0 ? (
              <>
                <FindExpand text=" " />
                <br />
              </>
            ) : null}
            <span className="whitespace-nowrap">
              {renderFindableLine(line)}
            </span>
          </Fragment>
        ))}
      </span>
    </FindableText>
  )
}

/**
 * Flex slot for board identity titles (stop name, cycle area, status group).
 * `layout="auto"` measures this box — it must be a flex item with a definite
 * width (`flex-1 min-w-0`), not shrink-wrapped to the glyphs.
 */
export const STATION_NAME_TITLE_SLOT_CLASS =
  "flex h-full min-w-0 flex-1 items-center"

/**
 * Trim the line box to cap-height → alphabetic baseline (not full
 * ascent/descent) before centering. A title is a label for what sits below
 * it, not what's above — centering on cap-height (rather than including
 * descender space) reads as anchored to its content and nudges the glyphs
 * down a touch versus dead-center. Same technique as chip labels
 * (`CHIP_CAP_TEXT_BOX_CLASS`), applied here at title scale.
 */
const STATION_NAME_TITLE_CLASS =
  "justify-center leading-none [text-box:trim-both_cap_alphabetic]"

/** One-line auto-fit name for board identity rows. Visual only — set `aria-label` on the heading. */
export const StationNameTitle = ({
  name,
  className,
  end,
}: {
  name: string
  className?: string
  /** Sits after the name (e.g. disruption chips). The slot stays `flex-1` so auto-fit still measures leftover width. */
  end?: ReactNode
}) => (
  <span
    className={cn(
      STATION_NAME_TITLE_SLOT_CLASS,
      end != null && "gap-x-1.5",
      className
    )}
  >
    <span aria-hidden="true" className="contents">
      <StationName
        name={name}
        layout="auto"
        maxLines={1}
        allowAbbreviation
        allowScaleDown
        className={cn(
          STATION_NAME_TITLE_CLASS,
          end != null && "w-auto flex-none"
        )}
      />
    </span>
    {end}
  </span>
)

/** @deprecated Prefer `StationName`. */
export const StationNameLabel = StationName

"use client"

import {
  forwardRef,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ClipboardEvent,
  type CSSProperties,
  type ReactNode,
} from "react"
import { useFindQuery } from "@/hooks/use-find-query"
import {
  isFindCovered,
  normalizeFindPhrase,
  phrasesToExpose,
} from "@/lib/tfl/find-coverage"

/** Chrome fires `beforematch` right before reveal but has no "unmatched" event. */
const REHIDE_DELAY_MS = 1500

const FIND_PHRASE_WRAPPER_CLASS =
  "absolute left-1/2 top-full z-20 mt-1 -translate-x-1/2 whitespace-nowrap"
const FIND_PHRASE_CHIP_CLASS =
  "inline-block bg-foreground px-1.5 py-0.5 text-[11px] font-medium leading-none text-background"

const escapeFindText = (value: string): string =>
  value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")

/**
 * Contiguous phrases find-in-page can already hit in `root`.
 * `display: none` / `hidden` nodes are skipped; `<br>` starts a new phrase.
 */
export const collectFindPhrasesFromElement = (root: Element): string[] => {
  const phrases: string[] = []
  let current = ""

  const flush = () => {
    const trimmed = normalizeFindPhrase(current)
    if (trimmed) phrases.push(trimmed)
    current = ""
  }

  const walk = (node: Node) => {
    if (node.nodeType === Node.TEXT_NODE) {
      current += node.textContent ?? ""
      return
    }
    if (node.nodeType !== Node.ELEMENT_NODE) return
    const el = node as Element
    if (el.tagName === "BR") {
      flush()
      return
    }
    if (el.hasAttribute("data-find-phrase")) return
    if (typeof getComputedStyle === "function") {
      const display = getComputedStyle(el).display
      if (display === "none") return
    }
    const hidden = el.getAttribute("hidden")
    if (el.hasAttribute("hidden") && hidden !== "until-found") return
    for (const child of el.childNodes) walk(child)
  }

  walk(root)
  flush()
  return phrases
}

/**
 * Canonical text for Cmd/Ctrl+F when paint wraps (`<br>`) or abbreviates —
 * find-in-page cannot match a phrase across the `<br>` between visual lines.
 *
 * Three constraints shape this:
 * 1. React serialises `hidden` as a boolean (`hidden=""` → `display: none`,
 *    unsearchable), so `until-found` has to be written as raw markup.
 * 2. `until-found` is ignored on `display: inline` / `none`, hence `absolute`.
 * 3. Reveal walks a match's *ancestors*, so the text sits in a child.
 *
 * Firefox / Safari have no `until-found`; they do match `opacity: 0` text.
 *
 * There's also no native "find closed" event, so this re-hides a beat after
 * reveal and restarts the countdown if the browser matches it again.
 *
 * Chips stay out of the DOM when the current find query already highlights
 * the painted copy (e.g. "Liverpool St" on a wrapped "Liverpool Street").
 */
const FindPhrase = ({
  text,
  coveredPhrases,
}: {
  text: string
  coveredPhrases: readonly string[]
}) => {
  const ref = useRef<HTMLSpanElement>(null)

  useLayoutEffect(() => {
    const el = ref.current?.firstElementChild
    if (!(el instanceof HTMLElement)) return

    if (!("onbeforematch" in document.body)) {
      el.removeAttribute("hidden")
      el.style.opacity = "0"
      return
    }

    let rehideTimer: ReturnType<typeof setTimeout> | undefined
    const handleBeforeMatch = () => {
      const selected = normalizeFindPhrase(
        document.getSelection()?.toString() ?? ""
      )
      if (selected && isFindCovered(selected, coveredPhrases)) {
        el.setAttribute("hidden", "until-found")
        return
      }
      if (rehideTimer) clearTimeout(rehideTimer)
      rehideTimer = setTimeout(() => {
        el.setAttribute("hidden", "until-found")
      }, REHIDE_DELAY_MS)
    }

    el.addEventListener("beforematch", handleBeforeMatch)
    return () => {
      el.removeEventListener("beforematch", handleBeforeMatch)
      if (rehideTimer) clearTimeout(rehideTimer)
    }
  }, [coveredPhrases, text])

  return (
    <span
      ref={ref}
      className="contents"
      data-find-phrase=""
      dangerouslySetInnerHTML={{
        __html: `<span hidden="until-found" data-find-phrase class="${FIND_PHRASE_WRAPPER_CLASS}"><span class="${FIND_PHRASE_CHIP_CLASS}">${escapeFindText(text)}</span></span>`,
      }}
    />
  )
}

export type FindableTextProps = {
  /** Canonical full text — used for aria-label, clipboard, and find-in-page. */
  text: string
  /** Extra searchable variants not already covered by the visible paint. */
  aliases?: readonly string[]
  /**
   * Phrases find-in-page can already hit in the paint (`<br>`-split lines,
   * abbreviation completions). When omitted, read from the paint DOM.
   */
  coveredPhrases?: readonly string[]
  /** Set when the visible paint is already the exact contiguous `text` — skips the redundant reveal chip. */
  paintMatchesText?: boolean
  /**
   * Escape hatch. Defaults to on — disable only for text that's intentionally
   * decorative/non-identity, and say why at the call site.
   */
  enableFind?: boolean
  className?: string
  style?: CSSProperties
  children: ReactNode
}

/**
 * Wraps identity text (station names, line names, stop names — anything a
 * user might expect to copy or find-in-page) so that when the visible paint
 * differs from the canonical string — real abbreviation, or a name split
 * across a `<br>` — Cmd/Ctrl+F and copy still resolve the full name.
 *
 * Hidden chips are mounted only for semantics the current find query cannot
 * already highlight in the paint. Plain CSS clipping (`truncate`,
 * `line-clamp`, `whitespace-nowrap`) never needs this: the DOM text is
 * unchanged, so the browser already finds and copies it correctly through
 * the clip. Reach for this only when the DOM text itself is not the
 * canonical string. See `.cursor/rules/findable-identity-text.mdc`.
 */
export const FindableText = forwardRef<HTMLSpanElement, FindableTextProps>(
  (
    {
      text,
      aliases = [],
      coveredPhrases: coveredPhrasesProp,
      paintMatchesText = false,
      enableFind = true,
      className,
      style,
      children,
    },
    ref
  ) => {
    const paintRef = useRef<HTMLSpanElement>(null)
    const findQuery = useFindQuery()
    const [observedCovered, setObservedCovered] = useState<string[]>(
      () => coveredPhrasesProp?.slice() ?? []
    )

    useLayoutEffect(() => {
      if (coveredPhrasesProp) return
      const el = paintRef.current
      if (!el) return
      const read = () => setObservedCovered(collectFindPhrasesFromElement(el))
      read()
      const target = el.parentElement ?? el
      const observer = new ResizeObserver(read)
      observer.observe(target)
      return () => observer.disconnect()
    }, [children, coveredPhrasesProp, findQuery, text])

    const coveredPhrases = coveredPhrasesProp ?? observedCovered

    const exposedPhrases = useMemo(() => {
      if (!enableFind) return []
      const candidates = paintMatchesText ? [...aliases] : [text, ...aliases]
      return phrasesToExpose(candidates, coveredPhrases, findQuery)
    }, [aliases, coveredPhrases, enableFind, findQuery, paintMatchesText, text])

    const handleCopy = (event: ClipboardEvent<HTMLSpanElement>) => {
      event.preventDefault()
      event.clipboardData.setData("text/plain", text)
    }

    return (
      <span
        ref={ref}
        className={className}
        style={style}
        aria-label={text}
        onCopy={handleCopy}
      >
        <span ref={paintRef} className="contents">
          {children}
        </span>
        {exposedPhrases.map((phrase) => (
          <FindPhrase
            key={phrase}
            text={phrase}
            coveredPhrases={coveredPhrases}
          />
        ))}
      </span>
    )
  }
)
FindableText.displayName = "FindableText"

import { formatStationName } from "@/lib/tfl/diagram-station"
import { applyStationAbbreviations } from "@/lib/tfl/station-abbreviations"

export {
  STATION_ABBREVIATIONS,
  applyStationAbbreviations,
} from "@/lib/tfl/station-abbreviations"

/** Measure text width in CSS px for a given font size. */
export type StationTextMeasure = (text: string, fontSizePx: number) => number

export type StationLabelFormatOptions = {
  /** Available label width in CSS px. */
  maxWidth: number
  /** Target font size in CSS px. */
  fontSize: number
  /** Prefer one line; allow two when needed (default 2). */
  maxLines?: 1 | 2
  /** Apply conservative TfL-style abbreviations only when needed. */
  allowAbbreviation?: boolean
  /** Shrink type as a last resort when still too wide. */
  allowScaleDown?: boolean
  /** Floor for scale-down (default 0.75). */
  minScale?: number
  /**
   * Hardwired lines (e.g. horizontal diagram crowding fixes).
   * Skips auto word-break selection when provided.
   */
  forcedLines?: readonly string[]
}

export type StationLabelFormatResult = {
  /** Display lines (1 or 2). Never splits mid-word. */
  lines: string[]
  /** Applied scale relative to requested fontSize (1 = full size). */
  scale: number
  /** True when an abbreviation was applied to fit. */
  abbreviated: boolean
  /** True when the result fits within maxWidth at the applied scale. */
  fits: boolean
  /** Normalised full name before line breaks. */
  displayName: string
}

/**
 * Conservative abbreviations used only when enabled and required to fit.
 * Prefer official short forms already common on TfL diagrams.
 * @deprecated Import from `@/lib/tfl/station-abbreviations` — re-exported here.
 */
// STATION_ABBREVIATIONS re-exported above from station-abbreviations.

/** Minimum type scale before giving up on fit (documented contract). */
export const STATION_LABEL_MIN_SCALE = 0.75

const tokenize = (name: string): string[] =>
  name.trim().split(/\s+/).filter(Boolean)

const applyAbbreviations = applyStationAbbreviations

const lineWidth = (
  text: string,
  fontSize: number,
  measure: StationTextMeasure
): number => measure(text, fontSize)

/**
 * All legal word-boundary splits into at most two lines.
 * Never breaks inside a token.
 */
export const stationLabelCandidates = (name: string): string[][] => {
  const tokens = tokenize(name)
  if (tokens.length === 0) return [[""]]
  if (tokens.length === 1) return [[tokens[0]!]]

  const candidates: string[][] = [[tokens.join(" ")]]
  for (let i = 1; i < tokens.length; i += 1) {
    candidates.push([tokens.slice(0, i).join(" "), tokens.slice(i).join(" ")])
  }
  return candidates
}

const scoreCandidate = (
  lines: string[],
  fontSize: number,
  maxWidth: number,
  measure: StationTextMeasure
): { fits: boolean; balance: number; widest: number; lineCount: number } => {
  const widths = lines.map((line) => lineWidth(line, fontSize, measure))
  const widest = Math.max(...widths)
  const narrowest = Math.min(...widths)
  return {
    fits: widest <= maxWidth + 0.5,
    balance: widest - narrowest,
    widest,
    lineCount: lines.length,
  }
}

const pickBestCandidate = (
  candidates: string[][],
  fontSize: number,
  maxWidth: number,
  maxLines: 1 | 2,
  measure: StationTextMeasure
): { lines: string[]; fits: boolean } => {
  const allowed =
    maxLines === 1 ? candidates.filter((c) => c.length === 1) : candidates

  let best = allowed[0] ?? [""]
  let bestScore = scoreCandidate(best, fontSize, maxWidth, measure)

  for (const candidate of allowed.slice(1)) {
    const score = scoreCandidate(candidate, fontSize, maxWidth, measure)
    const betterFit = score.fits && !bestScore.fits
    const sameFit = score.fits === bestScore.fits
    const preferFewerLines =
      sameFit && score.fits && score.lineCount < bestScore.lineCount
    const betterBalance =
      sameFit &&
      score.fits &&
      score.lineCount === bestScore.lineCount &&
      score.balance < bestScore.balance
    const lessOverflow =
      sameFit && !score.fits && score.widest < bestScore.widest

    if (betterFit || preferFewerLines || betterBalance || lessOverflow) {
      best = candidate
      bestScore = score
    }
  }

  return { lines: best, fits: bestScore.fits }
}

/**
 * Deterministic station-name layout for diagrams and the typography lab.
 * Prefer full one-line → balanced two-line → abbreviated → scale-down.
 */
export const formatStationLabel = (
  rawName: string,
  measure: StationTextMeasure,
  options: StationLabelFormatOptions
): StationLabelFormatResult => {
  const maxLines = options.maxLines ?? 2
  const allowAbbreviation = options.allowAbbreviation ?? false
  const allowScaleDown = options.allowScaleDown ?? true
  const minScale = options.minScale ?? STATION_LABEL_MIN_SCALE
  const displayName = formatStationName(rawName)
  const maxWidth = Math.max(1, options.maxWidth)
  const fontSize = Math.max(1, options.fontSize)

  if (options.forcedLines && options.forcedLines.length > 0) {
    const lines = [...options.forcedLines]
    const sized = fontSize
    const widest = Math.max(
      ...lines.map((line) => lineWidth(line, sized, measure))
    )
    return {
      lines,
      scale: 1,
      abbreviated: lines.join(" ") !== displayName,
      fits: widest <= maxWidth + 0.5,
      // Always the canonical single-line name — not the joined (possibly
      // abbreviated) visual lines. Copy / aria use this via formatStationName.
      displayName,
    }
  }

  const tryName = (
    name: string,
    abbreviated: boolean,
    scale: number
  ): StationLabelFormatResult => {
    const sized = fontSize * scale
    const { lines, fits } = pickBestCandidate(
      stationLabelCandidates(name),
      sized,
      maxWidth,
      maxLines,
      measure
    )
    return {
      lines,
      scale,
      abbreviated,
      fits,
      displayName: name,
    }
  }

  // 1. Full name at full size
  let result = tryName(displayName, false, 1)
  if (result.fits) return result

  // 2. Abbreviations at full size
  if (allowAbbreviation) {
    const abbreviatedName = applyAbbreviations(displayName)
    if (abbreviatedName !== displayName) {
      result = tryName(abbreviatedName, true, 1)
      if (result.fits) return result
    }
  }

  // 3. Scale down (full name first, then abbreviated)
  let smallest: StationLabelFormatResult = result
  if (allowScaleDown && minScale < 1) {
    const steps = 8
    for (let i = 1; i <= steps; i += 1) {
      const scale = Math.max(minScale, 1 - (i / steps) * (1 - minScale))
      const full = tryName(displayName, false, scale)
      if (full.fits) return full
      if (full.scale < smallest.scale) smallest = full

      if (allowAbbreviation) {
        const abbreviatedName = applyAbbreviations(displayName)
        if (abbreviatedName !== displayName) {
          const abbr = tryName(abbreviatedName, true, scale)
          if (abbr.fits) return abbr
          // Prefer the shorter visual when both overflow at the same scale.
          if (
            abbr.scale < smallest.scale ||
            (abbr.scale === smallest.scale && abbr.abbreviated)
          ) {
            smallest = abbr
          }
        }
      }
    }
  }

  // Nothing fitted — keep the smallest attempt, never bounce back to full size.
  return smallest
}

/**
 * Character-count fallback measure for SSR / tests.
 * Approximate Hammersmith One average advance ≈ 0.55em.
 */
export const approximateStationMeasure: StationTextMeasure = (
  text,
  fontSizePx
) => text.length * fontSizePx * 0.55

/** Build a canvas-backed measure for the live document font. */
export const createCanvasStationMeasure = (
  fontFamily: string,
  fontWeight = "400"
): StationTextMeasure => {
  if (typeof document === "undefined") return approximateStationMeasure

  const canvas = document.createElement("canvas")
  const ctx = canvas.getContext("2d")
  if (!ctx) return approximateStationMeasure

  return (text, fontSizePx) => {
    ctx.font = `${fontWeight} ${fontSizePx}px ${fontFamily}`
    return ctx.measureText(text).width
  }
}

/** Resolve the computed sans font stack from an element (or document body). */
export const resolveSansFontFamily = (el?: Element | null): string => {
  if (typeof window === "undefined") {
    return "Hammersmith One, system-ui, sans-serif"
  }
  const target = el ?? document.body
  const family = getComputedStyle(target).fontFamily
  return family || "Hammersmith One, system-ui, sans-serif"
}

export type DiagramConnection = {
  id: string
  name: string
  /** Hex colour for flag box; defaults to muted if omitted. */
  color?: string
  /** When true, use corporate blue text (Circle / H&C / W&C). */
  darkText?: boolean
}

export type DiagramStation = {
  id: string
  name: string
  /** Show interchange ring instead of a tick. */
  interchange?: boolean
  /** Optional connecting-line flag boxes (Tube / TfL modes — not National Rail). */
  connections?: DiagramConnection[]
  /**
   * National Rail interchange — rendered as the NR pictogram beside the name,
   * not as a §9 text flag.
   */
  nationalRail?: boolean
}

/** Adjacent route segment state for horizontal diagrams. */
export type DiagramSegmentState = "normal" | "out-of-use"

export type DiagramSegment = {
  fromStationId: string
  toStationId: string
  state: DiagramSegmentState
}

/**
 * Parentheticals that disambiguate which stop / line — strip these.
 * Keep place-name parentheses such as Kensington (Olympia).
 */
const LINE_DISAMBIGUATION_PARENS =
  /\s*\((?:[^)]*\b(?:Line|Lines|Bakerloo|Central|Circle|District|Piccadilly|Northern|Victoria|Jubilee|Metropolitan|Elizabeth|H&C|Dist|Picc|London)\b[^)]*)\)/gi

/** Short display name for diagrams (drop common TfL suffixes + line brackets). */
export const formatStationName = (name: string): string => {
  const raw = typeof name === "string" ? name : name == null ? "" : String(name)
  let next = raw
    .replace(/\s+Underground Station$/i, "")
    .replace(/-Underground(?:\s+Station)?$/i, "")
    .replace(/\s+DLR Station$/i, "")
    .replace(/\s+Rail Station$/i, "")
    .replace(/\s+Tram (?:Stop|Station)$/i, "")
    .replace(/\s+Station$/i, "")
    .trim()

  next = next.replace(LINE_DISAMBIGUATION_PARENS, "").trim()

  // Heathrow Terminals 2 & 3 → 2&3 (no spaces around &)
  next = next.replace(/(\d+)\s*&\s*(\d+)/g, "$1&$2")

  return next.replace(/\s+/g, " ").trim()
}

export const isLikelyInterchange = (stop: {
  lines?: { id?: string | null }[] | null
  modes?: string[] | null
}): boolean => {
  const lineCount = stop.lines?.filter((l) => l.id).length ?? 0
  if (lineCount > 1) return true
  const modes = stop.modes?.filter(Boolean) ?? []
  return modes.length > 1
}

import { formatStationName } from "@/lib/tfl/diagram-station"
import { neededFindPhrases, normalizeFindPhrase } from "@/lib/tfl/find-coverage"
import { STATION_ABBR_FIND_COMPLETIONS } from "@/lib/tfl/station-abbreviations"
import { stationSearchAliasForms } from "@/lib/tfl/station-name-match"

export { STATION_ABBR_FIND_COMPLETIONS } from "@/lib/tfl/station-abbreviations"
export {
  isFindCovered,
  neededFindPhrases,
  normalizeFindPhrase,
  shouldExposeFindPhrase,
} from "@/lib/tfl/find-coverage"

const APOSTROPHE_RE = /[\u2018\u2019\u02BC']/g

export const stripStationApostrophes = (value: string): string =>
  value.replace(APOSTROPHE_RE, "")

/** Normalise curly apostrophes to ASCII for alternate find queries. */
export const normalizeStationApostrophes = (value: string): string =>
  value.replace(/[\u2018\u2019\u02BC]/g, "'")

/**
 * Official copy / aria form: single line, full words, no diagram line breaks.
 */
export const stationCopyName = (
  rawName: string,
  accessibleName?: string
): string => {
  const next = (accessibleName ?? formatStationName(rawName))
    .replace(/\s+/g, " ")
    .trim()
  return next
}

/** `&` between words → `and` (keeps Heathrow-style `2&3` as `2 and 3`). */
export const stationAndForm = (value: string): string =>
  value
    .replace(/(\d+)\s*&\s*(\d+)/g, "$1 and $2")
    .replace(/\s*&\s*/g, " and ")
    .replace(/\s+/g, " ")
    .trim()

export const findCompletionForToken = (token: string): string | undefined => {
  if (!token || token === "&") return undefined
  const direct = STATION_ABBR_FIND_COMPLETIONS[token]
  if (direct) return direct
  const matched = Object.entries(STATION_ABBR_FIND_COMPLETIONS).find(
    ([abbr]) => abbr.toLowerCase() === token.toLowerCase()
  )
  return matched?.[1]
}

/**
 * Visual line text as find-in-page would see it after abbr completions
 * (e.g. "Liverpool St" → "Liverpool Street").
 */
export const expandStationLineForFind = (line: string): string =>
  line
    .split(/(\s+|&)/)
    .map((part) => {
      const completion = findCompletionForToken(part)
      return completion ? `${part}${completion}` : part
    })
    .join("")

/**
 * Phrases already contiguous in the DOM for Cmd/Ctrl+F.
 * Multi-line paint inserts `<br>`, which breaks matching across lines — so a
 * joined expansion is NOT treated as covered when there is more than one line.
 */
export const stationFindCoveredPhrases = (
  visualLines: readonly string[]
): string[] => {
  const covered: string[] = []
  for (const line of visualLines) {
    const trimmed = normalizeFindPhrase(line)
    if (trimmed) covered.push(trimmed)
    const expanded = normalizeFindPhrase(expandStationLineForFind(line))
    if (expanded) covered.push(expanded)
  }
  if (visualLines.length === 1) {
    const only = visualLines[0] ?? ""
    const joined = normalizeFindPhrase(expandStationLineForFind(only))
    if (joined) covered.push(joined)
  }
  return covered
}

/**
 * Extra phrases to expose to Cmd/Ctrl+F when they are not already covered by
 * contiguous DOM text (visible lines + inline abbreviation completions).
 * StationName renders these with `hidden="until-found"` (findable; shows on match).
 *
 * Contract: copy / aria / find all keep the canonical single-line full name,
 * even when the paint wraps or abbreviates (`<br>` breaks cross-line find).
 */
export const stationFindAliases = (
  copyName: string,
  visualLines: readonly string[]
): string[] => {
  const covered = stationFindCoveredPhrases(visualLines)
  const visualJoined = normalizeFindPhrase(visualLines.join(" "))

  return neededFindPhrases(
    [
      copyName,
      stationAndForm(copyName),
      normalizeStationApostrophes(copyName),
      stripStationApostrophes(copyName),
      stationAndForm(stripStationApostrophes(copyName)),
      normalizeStationApostrophes(stationAndForm(copyName)),
      stationAndForm(visualJoined),
      stripStationApostrophes(visualJoined),
      normalizeStationApostrophes(visualJoined),
      ...stationSearchAliasForms(copyName),
      ...stationSearchAliasForms(visualJoined),
    ],
    covered
  )
}

/**
 * Single source of truth for TfL-style station-name abbreviations.
 * Drives both visual shortening and Cmd/Ctrl+F completions.
 */

export type StationAbbreviationEntry = {
  /** Full word as it appears in canonical names (e.g. "Street"). */
  full: string
  /** Diagram short form (e.g. "St"). */
  short: string
  /**
   * Invisible suffix appended after `short` so find-in-page matches `full`
   * (e.g. "reet" → "Street").
   */
  findCompletion: string
